    await poner([{ ejercicio: 'curl_mancuernas', series: 1, pesos: [24], carga: 'par' }], '2026-09-15T23:30:00-03');
    await db.query(marcar);
    // Del 15 a la noche SI, salvo que "ahora" sea antes: el corte nunca pasa de now().
