console.log('\n149c. La rutina que se propone sola');
{
  const RU = await import('../nucleo/rutina.ts');
  const { restarDias } = await import('../nucleo/fechas.ts');
  const hoy = '2026-09-27';

  chequear('ejercicios en orden, sin repetir ni vacios',
    RU.ejerciciosEnOrden(['a', null, 'a', 'b', '', 'c']), ['a', 'b', 'c']);
  chequear('sin historia no propone nada', RU.rutinaParaHoy([], hoy), []);

  // (1) MISMO DIA DE LA SEMANA: 7 y 14 dias atras son el mismo dia; gana el mas
  // reciente (7). El de 3 dias es otro dia de la semana y no cuenta para esto.
  const sesiones = [
    { fecha: restarDias(hoy, 14), ejercicios: ['remo', 'banca', 'curl'] },
    { fecha: restarDias(hoy, 7), ejercicios: ['banca', 'remo', 'curl'] },
    { fecha: restarDias(hoy, 3), ejercicios: ['peso-muerto'] },
  ];
  chequear('propone lo del mismo dia, lo mas reciente',
    RU.rutinaParaHoy(sesiones, hoy), ['banca', 'remo', 'curl']);
  // UN DÍA SUELTO (15/10): "hice sentadilla en Smith una vez" no reescribe la rutina ni la pone primera.
  const lunes = (...dias) => dias.map(([hace, ejercicios]) => ({ fecha: restarDias(hoy, hace), ejercicios }));
  chequear('un ejercicio suelto no entra ni va primero; un día entero suelto deja el de antes; repetido, entra donde va', [
    RU.rutinaParaHoy(lunes([21, ['banca', 'remo', 'curl']], [14, ['banca', 'remo', 'curl']], [7, ['smith', 'banca', 'remo', 'curl']]), hoy),
    RU.rutinaParaHoy(lunes([14, ['banca', 'remo', 'curl']], [7, ['smith', 'estocadas']]), hoy),
    RU.rutinaParaHoy(lunes([21, ['banca', 'remo']], [14, ['smith', 'banca', 'remo']], [7, ['smith', 'banca', 'remo']]), hoy),
  ], [['banca', 'remo', 'curl'], ['banca', 'remo', 'curl'], ['smith', 'banca', 'remo']]);

  // El mismo dia pero de hace 5 semanas (35) queda fuera de la ventana de 4.
  const viejo = [
    { fecha: restarDias(hoy, 35), ejercicios: ['banca'] },
    { fecha: restarDias(hoy, 2), ejercicios: ['sentadilla'] },
  ];
  chequear('el mismo dia de hace 5 semanas no cuenta (cae a rotacion)',
    RU.rutinaParaHoy(viejo, hoy), ['sentadilla']);

  // (2) ROTACION: ciclo A,B,C,A,B; ninguno cae en el dia de hoy. Ultima = B;
  // la vez anterior que hice B, despues hice C -> propone C.
  const ciclo = [
    { fecha: restarDias(hoy, 20), ejercicios: ['A'] },
    { fecha: restarDias(hoy, 18), ejercicios: ['B'] },
    { fecha: restarDias(hoy, 16), ejercicios: ['C'] },
    { fecha: restarDias(hoy, 4), ejercicios: ['A'] },
    { fecha: restarDias(hoy, 2), ejercicios: ['B'] },
  ];
  chequear('rotacion: la que sigue a la ultima', RU.rutinaParaHoy(ciclo, hoy), ['C']);

  // (3) RE-ENGANCHE: cambio el primer ejercicio a 'remo' -> la cadena sale de la
  // sesion que lo tiene, de 'remo' en adelante.
  chequear('re-engancha desde el ejercicio elegido',
    RU.reengancharDesde(sesiones, 'remo'), ['remo', 'curl']);
  chequear('re-engancha a uno solo si nunca se hizo',
    RU.reengancharDesde(sesiones, 'zancada'), ['zancada']);

  // LA CADENA: el siguiente es el primero de la rutina que falta.
  chequear('el siguiente es el primero no hecho',
    RU.siguienteEnRutina(['banca', 'remo', 'curl'], ['banca']), 'remo');
  chequear('si ya hice todos, no hay siguiente',
    RU.siguienteEnRutina(['banca'], ['banca']), null);
}


console.log('\n150. La medalla que no baja nunca: el maximo historico');
{
  const { readFileSync: leer150 } = await import('node:fs');
  const { join: unir150 } = await import('node:path');
  const R150 = unir150(import.meta.dirname, '..');
  const de150 = (...p) => leer150(unir150(R150, ...p), 'utf8');
  const sinComentarios150 = (t) =>
    t.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/^\s*\/\/.*$/gm, ' ');

  const MED150 = await import('../nucleo/medallas.ts');

  // ---- EL MAXIMO, EJERCICIO POR EJERCICIO ----
  //
  // El percentil se recalcula siempre, con el peso corporal y el sexo de hoy;
  // lo que se muestra y se guarda es el mayor entre eso y lo que dio alguna
  // vez. Las dos cosas a la vez, que parecian incompatibles.
  const tope150 = (a, b) =>
    MED150.topeHistorico(a, b).sort((x, y) => (x.ejercicio < y.ejercicio ? -1 : 1));

  chequear('si hoy da mas, manda hoy',
    tope150([{ ejercicio: 'press_banca', percentil: 90 }], [{ ejercicio: 'press_banca', percentil: 80 }]),
    [{ ejercicio: 'press_banca', percentil: 90 }]);
  // ESTE ES EL CASO DEL PEDIDO: subiste de peso corporal, el mismo
  // levantamiento vale menos, y la medalla NO se mueve.
  chequear('si hoy da menos, manda lo guardado',
    tope150([{ ejercicio: 'press_banca', percentil: 70 }], [{ ejercicio: 'press_banca', percentil: 88 }]),
    [{ ejercicio: 'press_banca', percentil: 88 }]);

  // UNA MEDALLA GANADA NO SE DEVUELVE: si hoy no hay marca de ese ejercicio
  // —se borro, o el peso la dejo debajo del umbral— la fila vieja sigue.
  chequear('lo guardado que hoy no existe sigue estando',
    tope150([], [{ ejercicio: 'sentadilla', percentil: 96 }]),
    [{ ejercicio: 'sentadilla', percentil: 96 }]);
  chequear('y lo de hoy que no estaba guardado entra',
    tope150([{ ejercicio: 'sentadilla', percentil: 51 }], []),
    [{ ejercicio: 'sentadilla', percentil: 51 }]);

  // MEZCLA: cada ejercicio se decide solo.
  chequear('cada ejercicio va por su cuenta',
    tope150(
      [{ ejercicio: 'press_banca', percentil: 60 }, { ejercicio: 'sentadilla', percentil: 97 }],
      [{ ejercicio: 'press_banca', percentil: 84 }, { ejercicio: 'sentadilla', percentil: 90 }]
    ),
    [{ ejercicio: 'press_banca', percentil: 84 }, { ejercicio: 'sentadilla', percentil: 97 }]);

  // UNA FILA ROTA NO ROMPE NI PISA: viene de la base, y la base puede tener
  // cualquier cosa vieja adentro.
  chequear('un percentil que no es numero se ignora',
    tope150([{ ejercicio: 'press_banca', percentil: 75 }], [{ ejercicio: 'press_banca', percentil: null }]),
    [{ ejercicio: 'press_banca', percentil: 75 }]);

  // ---- EL MATERIAL SALE DEL MAXIMO, NO DE HOY ----
  const desdeTope = MED150.medallasDePercentiles(
    MED150.topeHistorico(
      [{ ejercicio: 'press_banca', percentil: 70 }],
      [{ ejercicio: 'press_banca', percentil: 88 }]
    )
  );
  chequear('con 70 hoy y 88 guardado, la medalla es planeta',
    desdeTope[0]?.material, 'planeta');
  chequear('y el globo dice el numero historico',
    desdeTope[0]?.percentil, 88);

  // ---- EL CAMINO REAL ----
  const per150 = sinComentarios150(de150('compartido', 'perfil.ts'));
  chequear('el perfil lee lo guardado antes de decidir',
    /from\('medallas'\)\.select\('ejercicio, percentil'\)/.test(per150), true);
  chequear('y aplica el tope historico', /topeHistorico\(hoy, viejas\)/.test(per150), true);
  // SI NO SE PUDO LEER LO GUARDADO NO SE ESCRIBE NADA. Sin las filas viejas el
  // maximo no es un maximo: es el valor de hoy, y guardarlo podria BAJAR un
  // record por una consulta que fallo.
  chequear('y si la lectura fallo no escribe', /if \(guardadas\.error\) return hoy;/.test(per150), true);

  // ---- LA FRASE DEJO DE HABLAR DE HOY ----
  //
  // Decia "este peso", que sonaba a lo que levantas ahora: con un numero
  // historico eso podia quedar mintiendo.
  const T150 = (await import('../nucleo/textos.ts')).T;
  chequear('la frase nombra la marca, no el peso de hoy',
    /esa marca/.test(T150.medallas.frase(5)), true);
  chequear('y ya no dice "este peso"', /este peso/.test(T150.medallas.frase(5)), false);
}


console.log('\n151. El aviso de que el motor no arranco (lo de Brave)');
{
  const { readFileSync: leer151 } = await import('node:fs');
  const { join: unir151 } = await import('node:path');
  const R151 = unir151(import.meta.dirname, '..');
  const de151 = (...p) => leer151(unir151(R151, ...p), 'utf8');
  const sinComentarios151 = (t) =>
    t.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/^\s*\/\/.*$/gm, ' ');

  const F151 = await import('../nucleo/fondo.ts');

  // ---- LOS CUATRO MOTIVOS, EN ORDEN ----
  //
  // Se ven todos igual en pantalla —no hay cuerpo— y son cosas distintas. El
  // orden es el mismo que el del codigo: si la preferencia dice que no, el
  // motor ni se importa, asi que preguntar por WebGL despues seria contar algo
  // que nunca llego a pasar.
  chequear('con la preferencia en nunca, es la preferencia',
    F151.porQueNoHayMotor('nunca', false, true), 'preferencia');
  chequear('y manda aunque tampoco haya WebGL',
    F151.porQueNoHayMotor('nunca', false, false), 'preferencia');

  // EL CASO DE BRAVE: su escudo contra huellas le miente a
  // hardwareConcurrency, la app lee "equipo flojo" y decide no cargar three.
  // No es que el motor falle: es que no se enciende.
  chequear('en auto y equipo flojo, es el equipo',
    F151.porQueNoHayMotor('auto', true, true), 'equipo');
  // PERO "SIEMPRE" GANA: si se pidio explicitamente, el equipo no decide.
  chequear('con siempre, el equipo flojo no manda',
    F151.porQueNoHayMotor('siempre', true, true) !== 'equipo', true);
  // Y NO SE SABE NO ES FLOJO: negarle el fondo a alguien por no poder medirlo
  // seria castigar la falta de dato.
  chequear('no saber si es flojo no cuenta como flojo',
    F151.porQueNoHayMotor('auto', null, true) !== 'equipo', true);

  chequear('si se podia cargar y no hay WebGL, es WebGL',
    F151.porQueNoHayMotor('auto', false, false), 'webgl');
  // EL UNICO QUE ES UN ERROR DE VERDAD: se pidio, se pudo, hay WebGL, y aun
  // asi no hay lienzo.
  chequear('y si todo estaba bien, se monto mal',
    F151.porQueNoHayMotor('auto', false, true), 'monto-mal');

  // ---- LO MUESTRA LA GALERIA, Y SOLO LA GALERIA ----
  //
  // A quien usa la app no le sirve saber que su navegador no da WebGL: no
  // tiene nada que hacer con eso, y el fondo de CSS esta para que no se note.
  const gal151 = sinComentarios151(de151('src', 'app', 'galeria', 'page.tsx'));
  chequear('la galeria muestra el aviso', /<AvisoDelMotor \/>/.test(gal151), true);
  chequear('y pregunta el motivo', /porQueNoHayMotor\(/.test(gal151), true);
  // SE MIRA SI HAY LIENZO, que es el unico hecho que no se puede discutir.
  chequear('mirando si hay lienzo', /'\.fondo-lienzo canvas'/.test(gal151), true);
  // Y SE SIGUE MIRANDO: aca el fondo se vuelve a montar con cada rango que se
  // toca, y un aviso pegado de un montaje viejo mentiria.
  chequear('y se sigue mirando, no una sola vez', /setInterval\(mirar/.test(gal151), true);

  const otras151 = ['src/components/FondoEspacial.tsx', 'movil/src/Inicio.tsx'];
  for (const f of otras151) {
    chequear('no avisa en ' + f,
      /porQueNoHayMotor/.test(de151(...f.split('/'))), false);
  }

  // ---- EL SONDEO DE WEBGL SUELTA EL CONTEXTO ----
  //
  // Un navegador permite unos pocos contextos vivos y el recolector tarda:
  // sin soltarlo, preguntar varias veces se come el cupo del motor de verdad.
  const lib151 = sinComentarios151(de151('src', 'lib', 'fondo.ts'));
  chequear('el sondeo de WebGL usa un lienzo suelto',
    /createElement\('canvas'\)/.test(lib151), true);
  chequear('y lo suelta a mano',
    /WEBGL_lose_context'\)\?\.loseContext\(\)/.test(lib151), true);
}


console.log('\n152. Las pantallas apiladas siempre tienen salida');
{
  const { readFileSync: leer152 } = await import('node:fs');
  const { join: unir152 } = await import('node:path');
  const R152 = unir152(import.meta.dirname, '..');
  const de152 = (...p) => leer152(unir152(R152, ...p), 'utf8');
  const sinComentarios152 = (t) =>
    t.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/^\s*\/\/.*$/gm, ' ');

  // ---- LO QUE ENCONTRO EL BARRIDO (25/9) ----
  //
  // Sin red, el perfil propio se abria, no podia traer los datos y mostraba el
  // cartel A PANTALLA COMPLETA: sin barra de pestanas —es una pantalla
  // apilada— y sin "Volver", porque esa rama no lo dibujaba. El unico boton
  // era "Reintentar", que sin senal no puede hacer nada. De ahi no se salia
  // mas que cerrando la app.
  //
  // Y NO ERA SOLO EL ERROR: mientras carga tampoco habia salida, en las tres.
  // Una consulta que tarda encierra igual que una que falla, y con mala senal
  // tardar mucho es lo normal.
  //
  // LA REGLA: en una pantalla apilada, la puerta se dibuja SIEMPRE y antes que
  // el contenido. No depende de que el contenido haya llegado.
  const apiladas152 = ['PerfilPropio', 'PerfilDeAmigo', 'MisMarcas'];
  for (const f of apiladas152) {
    const t = sinComentarios152(de152('movil', 'src', f + '.tsx'));
    chequear(f + ': la salida se arma una sola vez', /const salida = \(/.test(t), true);
    // Y SE DIBUJA EN TODAS LAS RAMAS TEMPRANAS: las dos que devuelven antes
    // del contenido son las que encerraban.
    const tempranas = t.split(/\n  if \(/).slice(1, 3);
    chequear(f + ': las dos ramas tempranas la dibujan',
      tempranas.length === 2 && tempranas.every((r) => /\{salida\}/.test(r)), true);
  }

  // ---- LAS PESTANAS QUE NO SE VEN TAMPOCO SE LEEN ----
  //
  // Las cinco estan montadas a la vez —es lo que arreglo el titileo— y el
  // overflow recorta lo que se VE, no lo que se LEE: VoiceOver recorria las
  // cinco pantallas seguidas. Salio del mismo barrido, que estando en Ajustes
  // se topo con un enlace de Stats.
  const pes152 = sinComentarios152(de152('movil', 'src', 'Pestanas.tsx'));
  chequear('la pestana que no esta no recibe toques',
    /pointerEvents=\{cual === pestana \? 'auto' : 'none'\}/.test(pes152), true);
  chequear('y tampoco la lee el lector de pantalla',
    /accessibilityElementsHidden=\{cual !== pestana\}/.test(pes152), true);

  // ---- Y EL BARRIDO DEJA DE CONFUNDIRSE DE PANTALLA ----
  //
  // Un texto suelto se encontraba en una pestana que no estaba: visible para
  // Playwright —esta dibujada, fuera del recorte— pero sin recibir toques, o
  // sea quince segundos esperando un click imposible, y reportado como "no se
  // pudo abrir" con la pantalla perfecta. Peor: para intentarlo, Playwright
  // ARRASTRA el contenedor y deja la tira a mitad de camino.
  const bar152 = de152('supabase', 'barrido-nativa.mjs');
  // Y CORRE SOLO EN EL CIERRE, que es lo que se pidio el 24/9: una sonda que
  // hay que acordarse de correr es una sonda que no corre.
  chequear('el barrido entra en el cierre',
    /npm run barrido/.test(JSON.parse(de152('package.json')).scripts.cierre), true);
  chequear('el barrido puede buscar dentro de una pestana',
    /carril-\$\{p\}/.test(bar152), true);
  chequear('y dentro de la hoja, que se dibuja en la raiz',
    /data-testid="hoja"/.test(bar152), true);
  chequear('la hoja lleva ese testID', /testID="hoja"/.test(de152('movil', 'src', 'Hoja.tsx')), true);
  // EL TITULO ENTERO: "Como se compara" a secas tambien es el enlace de Stats.
  chequear('y busca el titulo entero en Ajustes',
    /'Cómo se compara la fuerza'/.test(bar152), true);
}


console.log('\n153. Los bugs del gimnasio: el interbloqueo, la musica y la racha');
{
  const { readFileSync: leer153 } = await import('node:fs');
  const { join: unir153 } = await import('node:path');
  const R153 = unir153(import.meta.dirname, '..');
  const de153 = (...p) => leer153(unir153(R153, ...p), 'utf8');
  const sinComentarios153 = (t) =>
    t.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/^\s*\/\/.*$/gm, ' ');

  const lay153 = sinComentarios153(de153('movil', 'app', '_layout.tsx'));

  // ---- 1. EL INTERBLOQUEO DE AUTH, que era el bug mas grave ----
  //
  // "Cuando suena la alarma de fin de descanso se buguea todo: aparece
  // Reintentar y las paginas dejan de cargar, no puedo cambiar de pestana."
  //
  // El callback de onAuthStateChange corre CON EL CANDADO del cliente de auth
  // tomado, y getSession() espera ese mismo candado: el callback espera a la
  // llamada y la llamada al callback. A partir de ahi ningun pedido a Supabase
  // vuelve nunca, que es exactamente lo que se ve desde afuera.
  //
  // Desde el 4/10 el callback ya no decide solo "sin sesion": un aviso vacio que
  // no es una salida se pregunta con `mirar` (seccion 177). Lo que esto cuida
  // sigue igual, y se mira en el CUERPO del callback: ahi adentro no se toca
  // Supabase, y `mirar` solo se llama soltando antes el candado.
  const aviso153 = lay153.slice(lay153.indexOf('onAuthStateChange('), lay153.indexOf('data.subscription.unsubscribe'));
  chequear('el callback de auth existe y se encontro', aviso153.length > 40, true);
  chequear('el callback de auth no le pregunta nada a Supabase', /supabase\./.test(aviso153), false);
  chequear('y no llama a mirar adentro',
    /onAuthStateChange\(\(\) => mirar\(\)\)/.test(lay153), false);
  chequear('si tiene que preguntar, lo hace despues de soltar el candado',
    aviso153.replace(/setTimeout\(\(\) => void mirar\(\), 0\)/g, '').includes('mirar('), false);
  // LA SESION YA VIENE EN EL EVENTO: cuando viene, no hay nada que ir a buscar.
  chequear('usa la sesion que trae el evento', /trasElAviso\(evento, !!viva\)/.test(aviso153), true);

  // ---- 2. EL TOKEN SE RENUEVA SOLO CON LA APP ADELANTE ----
  //
  // La otra mitad. autoRefreshToken es un temporizador de JavaScript y en el
  // fondo iOS lo congela: una hora de gimnasio con el telefono en el bolsillo
  // puede volver con el token vencido y sin un solo intento hecho.
  chequear('se arranca la renovacion al volver al frente',
    /startAutoRefresh\(\)/.test(lay153), true);
  chequear('y se para al irse al fondo', /stopAutoRefresh\(\)/.test(lay153), true);
  chequear('mirando AppState', /AppState\.addEventListener\('change'/.test(lay153), true);

  // ---- 3. LA APP NO CORTA LA MUSICA. NUNCA. ----
  //
  // "Se frena mi musica: al entrar a la app, y al elegir el tiempo de
  // descanso." No era un bug: 'doNotMix' no dice "baja lo que suena mientras
  // dura el bip", declara que esta app no comparte la salida de audio, y el
  // sistema lo aplica AL ACTIVAR LA SESION.
  const aud153 = sinComentarios153(de153('movil', 'src', 'plataforma', 'audio.ts'));
  chequear('el audio se mezcla con lo que suene', /interruptionMode: 'mixWithOthers'/.test(aud153), true);
  chequear('y ya no interrumpe', /interruptionMode: 'doNotMix'/.test(aud153), false);
  // LA CATEGORIA SE DECLARA AL ARRANCAR, no al abrir el descanso: si no la
  // tocamos nosotros la toca el modulo con lo que traiga de fabrica, y ahi la
  // musica ya se freno.
  chequear('la sesion de audio se declara en la raiz de la app',
    /plataforma\.audio\.preparar\(\)/.test(lay153), true);
  chequear('y una sola vez', /if \(modoPuesto\) return;/.test(aud153), true);
  // Y EL TEXTO DE AJUSTES DICE LO QUE PASA AHORA, que es lo contrario.
  const T153 = (await import('../nucleo/textos.ts')).T;
  chequear('Ajustes ya no promete cortar la musica',
    /[Cc]orta tu música/.test(T153.ajustes.sonidoRespeta), false);
  chequear('dice que suena por encima', /por encima/.test(T153.ajustes.sonidoRespeta), true);

  // ---- 4. LA CAMPANA SE ESCUCHA ----
  //
  // "Se escucha poco. Con musica puesta no la escuche." El archivo estaba al
  // 24,7% de la escala: bajito antes de salir del parlante.
  {
    const b = leer153(unir153(R153, 'movil', 'assets', 'bip.wav'));
    const buf = Buffer.from(b, 'binary');
    let pico = 0;
    for (let i = 44; i + 1 < buf.length; i += 2) {
      const v = Math.abs(buf.readInt16LE(i));
      if (v > pico) pico = v;
    }
    chequear('la campana usa casi toda la escala', pico / 32767 > 0.9, true);
    // Y DURA LO SUFICIENTE para repetirse: con musica, lo que hace que un
    // aviso se note no es solo el nivel, es que insista.
    const dur = (buf.length - 44) / 2 / buf.readUInt32LE(24);
    chequear('y dura mas de medio segundo', dur > 0.6, true);
  }

  // ---- 5. LA RACHA NO SE ESCONDE MAS ----
  //
  // "La racha desaparece cuando inicio el entrenamiento. Ya pedi que se
  // quedara y quedo al reves. El numero tiene que estar siempre."
  const ini153 = sinComentarios153(de153('movil', 'src', 'Inicio.tsx'));
  const desdeRacha = ini153.indexOf('RachaConRotulo racha=');
  const tramo = ini153.slice(Math.max(0, desdeRacha - 900), desdeRacha);
  chequear('la racha no cuelga de que no haya sesion',
    /\{!sesion\.estado\.corriendo && \(\s*<>/.test(tramo), false);
  // LA TIRA DE LA SEMANA SI SE VA: son siete puntos que no cambian en medio de
  // una sesion y empujan el bloque, que es lo que se toca doce veces.
  chequear('la tira de la semana sigue escondida entrenando',
    // Desde el 21/10 la tira lleva también el margen de debajo de las vidas.
    /\{!sesion\.estado\.corriendo && \(\s*<View style=\{\[estilos\.tira[^>]*testID="tira-inicio">/.test(ini153), true);

  // ---- 6. SE PUEDE ENTRAR AL PERFIL ENTRENANDO ----
  //
  // Con la sesion corriendo aparecen DOS chips a la derecha, y la fila del
  // nombre no cedia: se salia de la pantalla y quedaba sin nada tocable.
  chequear('la fila del nombre se achica', /flexShrink: 1, minWidth: 96/.test(ini153), true);
  chequear('el nombre cede antes que la fila', /usuario: \{[^}]*flexShrink: 1/.test(ini153), true);
  chequear('y los chips no se achican', /sesionViva: \{[^}]*flexShrink: 0/.test(ini153), true);
  chequear('el nombre no se parte en dos renglones', /numberOfLines=\{1\}/.test(ini153), true);
}


console.log('\n154. El entrenamiento: el menos, el peso por lado y los sin peso');
{
  const { readFileSync: leer154 } = await import('node:fs');
  const { join: unir154 } = await import('node:path');
  const R154 = unir154(import.meta.dirname, '..');
  const de154 = (...p) => leer154(unir154(R154, ...p), 'utf8');
  const sinComentarios154 = (t) =>
    t.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/^\s*\/\/.*$/gm, ' ');

  // ---- EL − AL LADO DEL +, DEL MISMO ALTO ----
  //
  // "En vez de un + grande, un + y un −. Bajar series hoy es muy tosco."
  // Sacar una serie estaba en un renglon de texto abajo de todo, mientras
  // sumarla era un boton de media pantalla. Contar mal para abajo pasa igual
  // de seguido que contar mal para arriba.
  const blo154 = sinComentarios154(de154('movil', 'src', 'Bloque.tsx'));
  chequear('el menos es un boton grande, no un renglon de texto',
    /estilos\.mas, estilos\.menos/.test(blo154), true);
  // EL + SIGUE MANDANDO: tres cuartos contra un cuarto. Doce sumas contra una
  // resta; del mismo tamano seria pedirle a la mano que apunte doce veces.
  chequear('el + se lleva tres cuartos del ancho', /masAncho: \{ flex: 3/.test(blo154), true);
  chequear('y el − un cuarto', /menos: \{ flex: 1/.test(blo154), true);
  // SE APAGA EN CERO EN VEZ DE DESAPARECER: un boton que aparece y se va mueve
  // el + de lugar justo cuando se lo esta tocando.
  chequear('el − se apaga en cero, no se esconde', /menosApagado/.test(blo154), true);
  chequear('y ya no esta el renglon de texto de sacar serie',
    /estilos\.texto\} onPress=\{alRestar\}/.test(blo154), false);

  // ---- "POR LADO" SUMA LOS DOS LADOS ----
  //
  // Ya probado en la 83 y la 90; aca va lo que ata las dos puntas: que el
  // catalogo no siga llamando 'una' a lo que se hace con las dos manos.
  const cat154 = de154('supabase', 'schema.sql');
  const tramo154 = cat154.slice(cat154.indexOf("set carga = 'una' where id in ("));
  const hasta154 = tramo154.slice(0, tramo154.indexOf(');'));
  for (const e of ['sentadilla_goblet', 'pullover', 'triceps_mancuerna']) {
    chequear(e + ' ya no es un lado por vez', hasta154.includes(e), false);
  }
  for (const e of ['remo_mancuerna', 'curl_concentrado', 'patada_triceps']) {
    chequear(e + ' si es un lado por vez', hasta154.includes(e), true);
  }
  // Y LA MIGRACION EXISTE PARA LA BASE QUE YA ESTA ANDANDO.
  chequear('hay migracion para reclasificarlos',
    /set carga = 'total'/.test(de154('supabase', 'migracion-47-una-suma-los-dos-lados.sql')), true);
  // EL TEXTO DE LA OPCION DEJA DE DECIR "ese peso": el numero es el de UN lado.
  const T154 = (await import('../nucleo/textos.ts')).T;
  chequear('la opcion dice que el numero es el de un lado',
    /de un lado/.test(T154.sesion.cargaOpcion.una), true);

  // ---- LOS EJERCICIOS SIN PESO NO LLENAN LA LISTA ----
  //
  // "Los ejercicios sin peso registrado no tienen que aparecer con peso. En la
  // web creo que ya estaba arreglado." Y estaba: alla se esconden detras de un
  // toque desde el 22/9, y en el telefono se habian quedado sin portar.
  const st154 = sinComentarios154(de154('movil', 'src', 'Stats.tsx'));
  chequear('el telefono lista solo los que tienen peso',
    /const conPeso = g\.filas\.filter\(\(f\) => f\.maximo\)/.test(st154), true);
  chequear('con la puerta para ver los otros', /verLosOtros\(faltan\)/.test(st154), true);
  // SI NO HAY NINGUNO se muestran igual: "ver los otros 12" sobre la nada es
  // una puerta a un cuarto vacio.
  chequear('y si no hay ninguno con peso, se muestran todos',
    /conPeso\.length === 0/.test(st154), true);
  chequear('la puerta no aparece sobre la nada',
    /faltan > 0 && conPeso\.length > 0/.test(st154), true);
}


console.log('\n155. El album: pasar con el dedo y dos botones que se ven');
{
  const { readFileSync: leer155 } = await import('node:fs');
  const { join: unir155 } = await import('node:path');
  const R155 = unir155(import.meta.dirname, '..');
  const de155 = (...p) => leer155(unir155(R155, ...p), 'utf8');
  const sinComentarios155 = (t) =>
    t.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/^\s*\/\/.*$/gm, ' ');

  const alb155 = sinComentarios155(de155('movil', 'src', 'Album.tsx'));

  // ---- 20. SE PASA CON EL DEDO ----
  //
  // Era lo unico que faltaba respecto de la web y, ademas, lo unico que uno
  // intenta: en un visor a pantalla completa nadie busca una flecha, arrastra.
  chequear('hay gesto de arrastre', /PanResponder\.create/.test(alb155), true);
  // Desde el 8/10 lo que se mueve es la tira entera: su lugar más el dedo (sección 196).
  chequear('y la foto se mueve con el dedo', /onPanResponderMove: \(_e, g\) => desliz\.setValue\(g\.dx\)/.test(alb155) && /translateX: corrimiento/.test(alb155), true);
  // MAS HORIZONTAL QUE VERTICAL Y CON MARGEN: un toque para cerrar mueve el
  // dedo uno o dos pixeles, y sin margen cada toque arrancaria un arrastre.
  chequear('no se dispara con un toque',
    /Math\.abs\(g\.dx\) > 8 && Math\.abs\(g\.dx\) > Math\.abs\(g\.dy\)/.test(alb155), true);
  // DISTANCIA O VELOCIDAD: solo por distancia, un movimiento corto y decidido
  // no pasa; solo por velocidad, un arrastre lento y largo tampoco. Umbral
  // bajado el 27/9 (45px / 0,25) porque con 70/0,4 "solo andaban los botones".
  chequear('pasa por distancia o por tiron',
    /Math\.abs\(g\.dx\) > 45 \|\| Math\.abs\(g\.vx\) > 0\.25/.test(alb155), true);
  // EL GESTO LEE EL ESTADO POR REFERENCIA: un PanResponder guarda las funciones
  // que tenia al crearse, y con el estado de cada dibujo el primer arrastre
  // sobre la segunda foto usaria el indice de la primera.
  chequear('el indice viaja en una ref', /abiertaRef\.current = abierta/.test(alb155), true);
  chequear('y la cantidad tambien', /cuantasRef\.current = celdas\.length/.test(alb155), true);
  // LAS FLECHAS SE QUEDAN: sirven para el lector de pantalla y para saber que
  // hay mas de una.
  chequear('las flechas siguen estando', /T\.album\.siguiente/.test(alb155), true);

  // ---- 21. LOS DOS PARECEN BOTONES ----
  //
  // "No parecen botones, parecen frases chicas." Y el de quitar lo era
  // literalmente: texto suelto, del mismo tamano y color que la fecha de al
  // lado.
  chequear('quitar es una pildora, no texto suelto',
    /style=\{estilos\.pastilla\} onPress=\{\(\) => setConfirmando\(true\)\}/.test(alb155), true);
  chequear('y ya no hay texto suelto de accion', /estilos\.accion\}/.test(alb155), false);
  // CONFIRMAR DICE QUE HACE, no "Si": con dos pildoras iguales al lado, "Si" y
  // "No" obligan a acordarse de la pregunta que ya no esta.
  const T155 = (await import('../nucleo/textos.ts')).T;
  chequear('el boton de confirmar dice que hace', /quitarla/i.test(T155.album.quitarSi), true);
  chequear('y va en rojo', /pastillaRoja/.test(alb155), true);
}


console.log('\n156. El planeta esta siempre, y fuera de Inicio se ve borroso');
{
  const { readFileSync: leer156 } = await import('node:fs');
  const { join: unir156 } = await import('node:path');
  const R156 = unir156(import.meta.dirname, '..');
  const de156 = (...p) => leer156(unir156(R156, ...p), 'utf8');
  const sinComentarios156 = (t) =>
    t.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/^\s*\/\/.*$/gm, ' ');

  // ---- EL CUERPO YA NO DESAPARECE AL CAMBIAR DE PESTANA ----
  //
  // "Al volver a Inicio el planeta aparece de la nada." Y aparecia porque en
  // las otras cuatro NO EXISTIA: pedian `soloEstrellas`, o sea cielo sin
  // cuerpo, y eso es OTRA escena —otra clave, otro montaje—. Volver a Inicio
  // obligaba a construirlo, y construirlo es lo que se veia.
  for (const f of ['Ranking', 'Album', 'Stats', 'Ajustes']) {
    chequear(f + ' ya no pide el cielo sin cuerpo',
      /soloEstrellas/.test(sinComentarios156(de156('movil', 'src', f + '.tsx'))), false);
  }
  // LA OPCION SIGUE EXISTIENDO en el motor: la usa el estado vacio, y sacarla
  // seria tirar una pieza que anda por un uso que cambio.
  chequear('pero el motor la sigue teniendo',
    /soloEstrellas/.test(de156('compartido', 'motor', 'escena.ts')), true);

  // ---- EL DESENFOQUE SIGUE AL DEDO ----
  const pes156 = sinComentarios156(de156('movil', 'src', 'Pestanas.tsx'));
  const des156 = sinComentarios156(de156('movil', 'src', 'desenfoqueDelFondo.ts'));
  const fon156 = sinComentarios156(de156('movil', 'src', 'FondoRaiz.tsx'));

  // SALE DE DONDE ESTA LA TIRA, no de que pestana va a quedar activa: eso es lo
  // que hace que baje MIENTRAS arrastras en vez de saltar al soltar.
  chequear('el desenfoque se mide contra la posicion de la tira',
    /const \{ asoma, x \} = arrastre\(/.test(pes156) && /ponerDesenfoque\(desenfoqueEn\(x, ancho\)\)/.test(pes156), true);
  chequear('y al soltar va a donde va la tira',
    /ponerDesenfoque\(desenfoqueEn\(llega, ancho\)\)/.test(pes156), true);
  const iIrA156 = pes156.indexOf('const irA = useCallback(');
  const irA156 = pes156.slice(iIrA156, pes156.indexOf('eventos.escuchar(IR_A_PESTANA', iIrA156));
  chequear('tocar una pestana tambien lo mueve',
    /const llega = reposo\(ORDEN\.indexOf\(destino\), ancho\);\s*ponerDesenfoque\(desenfoqueEn\(llega, ancho\)\)/.test(irA156), true);

  // ---- CADA PESTANA TIENE SU TECHO (25/9) ----
  //
  // "En Stats baja el desenfoque, no lo saques del todo." Stats es la pantalla
  // mas cargada de la app —dos graficos, el volumen, el calendario— y ahi el
  // fondo ya compite con el contenido aunque este nitido; desenfocarlo a fondo
  // es ademas plata gastada, porque no se ve nada del planeta atras de todo eso.
  chequear('Inicio en cero y Stats a menos de la mitad',
    /const DESENFOQUE: number\[\] = \[0, 1, 1, 0\.45, 1\]/.test(pes156), true);
  // SE INTERPOLA ENTRE VECINOS: del Album a Stats el nivel baja de a poco en
  // vez de pegar un escalon al llegar.
  chequear('y se interpola entre los dos vecinos',
    /return a \+ \(b - a\) \* \(i - Math\.floor\(i\)\)/.test(pes156), true);

  // SE AVISA EN PASOS ENTEROS: un gesto manda sesenta eventos por segundo y el
  // desenfoque tiene catorce valores distintos. Avisar en cada pixel seria un
  // dibujado de la raiz por cuadro para no cambiar nada.
  chequear('se avisa por escalones, no por pixel', /if \(nuevo === nivel\) return;/.test(des156), true);

  // NUNCA CON `filter`, y esto es una cicatriz: para desenfocar, iOS RASTERIZA
  // la vista, y una vista de OpenGL no tiene su contenido en la capa sino en un
  // framebuffer de la GPU que el rasterizador no lee. Lo que salia de ahi no
  // era el planeta borroso: era la capa vacia, o sea BLANCO. En el navegador
  // andaba —ahi `filter` es CSS y si funciona sobre un canvas— y por eso paso.
  //
  // EL CHEQUEO SE QUEDA PARA SIEMPRE: es barato, y el bug era de los que
  // llegan al telefono sin que nada se ponga rojo antes.
  chequear('el GLView no se desenfoca con filter', /filter: \[\{ blur:/.test(fon156), false);

  // DOS CAPAS, Y NINGUNA TOCA EL GLView (25/9).
  //
  // 1. EL VELO: una vista opaca del color del fondo. No desenfoca; empuja el
  //    planeta hacia atras. Bajo de 0.4 a 0.2 cuando entro el desenfoque de
  //    verdad: los dos al maximo tapaban el planeta en vez de desenfocarlo.
  chequear('el velo extra sube con la distancia a Inicio',
    /opacity: desenfoque \* 0\.2/.test(fon156), true);
  // 2. EL DESENFOQUE DE VERDAD, con expo-blur. Un UIVisualEffectView no
  //    rasteriza a nadie: desenfoca lo que quedo DETRAS suyo una vez ya
  //    compuesto en pantalla, GL incluido. Es justo lo que filter no puede.
  chequear('y encima va un BlurView, que si puede con GL',
    /<BlurView[\s\S]*?intensity=\{Math\.round\(desenfoque \* \d+\)\}/.test(fon156), true);
  // SOLO SE MONTA CUANDO HACE FALTA: un UIVisualEffectView no es gratis ni con
  // intensidad cero, y en Inicio —donde el planeta importa— no tiene que estar.
  chequear('y no existe en Inicio', /\{desenfoque > 0 && \(\s*<>/.test(fon156), true);
  // LAS DOS VIAJAN JUNTAS: expo-blur mueve la huella, asi que una build que no
  // lo tiene no puede recibir este JS. No hay que cuidar que el velo sobre.
  chequear('expo-blur esta en las dependencias',
    /"expo-blur":/.test(de156('movil', 'package.json')), true);
}


console.log('\n157. La pantalla de bloqueo: el timer que se caia y la campana');
{
  const { readFileSync: leer157 } = await import('node:fs');
  const { join: unir157 } = await import('node:path');
  const R157 = unir157(import.meta.dirname, '..');
  const de157 = (...p) => leer157(unir157(R157, ...p), 'utf8');

  const wid157 = de157('movil', 'targets', 'descanso', 'index.swift');

  // ---- 5. EL TIMER "SE QUEDABA CARGANDO" ----
  //
  // No se quedaba cargando: se CAIA. `Date.now...fin` es un ClosedRange, y un
  // rango cerrado exige que el principio no sea mayor que el final. Mientras el
  // descanso corre, `fin` esta en el futuro; al llegar a cero —que es
  // exactamente cuando uno mira el telefono— pasa al pasado, el rango se vuelve
  // invalido y Swift corta ahi. Lo que se ve cuando un widget se cae es el
  // rectangulo vacio del sistema.
  chequear('la cuenta solo se dibuja si falta tiempo',
    /if termino \{[\s\S]*?Text\("0:00"\)/.test(wid157), true);
  chequear('y el rango vive en la rama de "todavia no"',
    /\} else \{[\s\S]*?Text\(timerInterval: Date\.now\.\.\.fin/.test(wid157), true);
  // DOS PREGUNTAS Y NO UNA: `isStale` es lo que el sistema sabe sin la app
  // viva; la comparacion contra el reloj cubre el dibujo de justo despues.
  chequear('termino se decide con isStale y con el reloj',
    /context\.isStale \|\| context\.state\.fin <= Date\(\)/.test(wid157), true);

  // ---- 7. EL FINAL SE AVISA EN LA MISMA TARJETA ----
  chequear('la tarjeta dice LISTO al terminar', /"LISTO" : "DESCANSO"/.test(wid157), true);
  chequear('y lo dice tambien en la isla', (wid157.match(/"LISTO" : "DESCANSO"/g) ?? []).length >= 2, true);
  // Y CON LA APP ADELANTE NO HAY CARTEL DEL SISTEMA: la pantalla del descanso
  // ya avisa —cambia de color, vibra y suena— y el cartel encima era la otra
  // mitad de "una sola cosa, no dos".
  const avi157 = de157('movil', 'src', 'plataforma', 'avisos.ts');
  chequear('sin cartel con la app abierta', /shouldShowBanner: false/.test(avi157), true);
  // Desde el 8/10 los ecos del aviso largo no suenan con la app abierta; el primero sí (sección 197).
  // Desde el 12/10 suena salvo que la persona haya apagado "Sonido al terminar" (sección 197).
  // Desde el 14/10 no suena: con la app adelante suena la app, en el cero (sección 217).
  chequear('pero con sonido', /shouldPlaySound: sonidoAlFrente/.test(avi157), true);

  // ---- 8. LA CAMPANA SE ESCUCHA ----
  //
  // El sonido de fabrica de iOS es corto y discreto a proposito —esta pensado
  // para un mensaje— y contra musica con auriculares no llega.
  chequear('la notificacion usa la campana nuestra', /sound: conSonido \? 'campana\.wav' : false/.test(avi157), true);
  // TIME SENSITIVE: atraviesa el modo de concentracion. Un temporizador que no
  // suena por tener "No molestar" es un temporizador roto, y es justo cuando
  // se usa.
  chequear('y atraviesa el modo de concentracion',
    /interruptionLevel: 'timeSensitive'/.test(avi157), true);
  // EL ARCHIVO VA EN EL BUNDLE, no en el JavaScript: lo reproduce el sistema.
  const app157 = JSON.parse(de157('movil', 'app.json'));
  const notif157 = app157.expo.plugins.find((x) => Array.isArray(x) && x[0] === 'expo-notifications');
  chequear('la campana se declara en app.json',
    (notif157?.[1]?.sounds ?? []).some((s) => /campana\.wav$/.test(s)), true);
  chequear('y el archivo existe', de157('movil', 'assets', 'campana.wav').length > 1000, true);

  // ---- LOS COLORES DEL WIDGET SIGUEN SIENDO LOS DE LA APP ----
  //
  // Un target de Apple no puede importar TypeScript, asi que estan copiados.
  // Esto compara los dos lados: si alguien cambia la paleta, se canta en vez de
  // quedar de otro color para siempre en la pantalla que nadie mira dos veces.
  const cfg157 = de157('movil', 'targets', 'descanso', 'expo-target.config.js');
  const col157 = de157('movil', 'src', 'colores.ts');
  for (const [nombre, hex] of [['fondo', '#05060a'], ['tinta', '#e8ecf6'], ['sub', '#8a93a8'], ['claro', '#c4c2ba']]) {
    chequear('el widget y la app comparten ' + nombre,
      cfg157.includes(nombre + ": '" + hex + "'") && col157.includes(nombre + ": '" + hex + "'"), true);
  }
}


console.log('\n158. Los nombres de verdad, el rango por musculo y la tarjeta');
{
  const { readFileSync: leer158 } = await import('node:fs');
  const { join: unir158 } = await import('node:path');
  const R158 = unir158(import.meta.dirname, '..');
  const de158 = (...p) => leer158(unir158(R158, ...p), 'utf8');
  const sinComentarios158 = (t) =>
    t.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/^\s*\/\/.*$/gm, ' ');

  // ---- LOS NOMBRES ----
  //
  // "Pone los nombres como se conocen de verdad, no la traduccion literal."
  // Un ejercicio que no se reconoce en la lista NO SE ELIGE: se elige el de al
  // lado, o se deja el bloque sin ejercicio, y ahi la app pierde el dato que
  // vino a guardar.
  const nombres158 = new Map(
    [...de158('supabase', 'schema.sql').matchAll(/\('([a-z_0-9]+)',\s*'((?:[^']|'')*)'/g)].map((m) => [m[1], m[2]])
  );
  for (const [id, nombre] of [
    ['buenos_dias', 'Good morning'],
    ['peso_muerto_rigidas', 'Peso muerto stiff'],
    ['subida_cajon', 'Step up'],
    ['encogimientos', 'Shrugs'],
    ['giros_rusos', 'Russian twist'],
    ['sentadilla_smith', 'Sentadilla en Smith'],
    ['fondos', 'Fondos en paralelas'],
    ['flexiones', 'Flexiones'],
    ['aperturas', 'Aperturas con mancuernas'],
    ['pec_deck', 'Peck deck'],
  ]) {
    chequear(id + ' se llama como se dice', nombres158.get(id), nombre);
  }
  // LOS IDS NO CAMBIAN, y es lo que hace esto seguro: los bloques ya anotados
  // guardan el id, asi que el historial entero sigue apuntando al mismo lugar.
  const mig158 = de158('supabase', 'migracion-48-nombres-de-verdad.sql');
  chequear('la migracion solo toca nombres', /set nombre =/.test(mig158), true);
  chequear('y no toca ningun id', /set id =/.test(mig158), false);
  // Y LOS DOS QUE QUEDARON COMO ESTABAN, con el mismo criterio: lo que la gente
  // dice de verdad.
  chequear('la patada de gluteo se queda', nombres158.get('patada_gluteo'), 'Patada de glúteo en polea');
  chequear('y los abdominales en polea tambien', nombres158.get('abdominales_polea'), 'Abdominales en polea');

  // ---- EL RANGO DE REFERENCIA POR MUSCULO ----
  //
  // "Las barras no comunican nada": estaban escaladas contra tu propio maximo,
  // asi que una barra llena podia ser 4 series o 40. Sin referencia, una barra
  // solo dice "mas que la otra", y eso ya lo dice el numero.
  const V158 = await import('../nucleo/volumen.ts');
  chequear('el rango es 10 a 20', [V158.SERIES_POR_SEMANA.minimo, V158.SERIES_POR_SEMANA.maximo], [10, 20]);
  chequear('nada no es poco', V158.comoVaElMusculo(0), 'nada');
  chequear('nueve es poco', V158.comoVaElMusculo(9), 'poco');
  chequear('diez ya esta dentro', V158.comoVaElMusculo(10), 'dentro');
  chequear('veinte todavia', V158.comoVaElMusculo(20), 'dentro');
  chequear('veintiuno es mucho', V158.comoVaElMusculo(21), 'mucho');
  // EL TOPE ES FIJO Y AHI ESTA LA GRACIA: con una escala que se estirara con la
  // fila mas alta, la franja se moveria de lugar en cada pantalla y volveria a
  // no significar nada.
  chequear('la pista llega a veinticuatro', V158.TOPE_DE_PISTA, 24);
  chequear('doce ocupa la mitad', V158.porcionDePista(12), 0.5);
  chequear('y pasarse no desborda', V158.porcionDePista(40), 1);
  const st158 = sinComentarios158(de158('movil', 'src', 'Stats.tsx'));
  chequear('Stats dibuja la franja', /estilos\.franja/.test(st158), true);
  chequear('y ya no tiene el selector de kilos', /T\.volumen\.enKilos/.test(st158), false);
  // LOS KILOS POR MUSCULO NO SE PUEDEN COMPARAR ENTRE SI: una semana con prensa
  // aplasta a todos los demas.
  chequear('ni suma kilos por musculo', /kilosLindos\(leida/.test(st158), false);

  // ---- EL ALBUM CONTESTA DOS PREGUNTAS ----
  const A158 = await import('../nucleo/album.ts');
  chequear('el mes cuenta fotos y dias',
    A158.resumenDelMes([{ fecha: '2026-09-01' }, { fecha: '2026-09-01' }, { fecha: '2026-09-03' }]),
    { fotos: 3, dias: 2 });
  // COMPARAR UNA FOTO CON SI MISMA NO ES COMPARAR, y dos del mismo dia tampoco:
  // no paso nada entre una y otra.
  chequear('con una sola no hay comparacion', A158.primeraYUltima([{ fecha: '2026-09-01' }]), null);
  chequear('con dos del mismo dia tampoco',
    A158.primeraYUltima([{ fecha: '2026-09-01' }, { fecha: '2026-09-01' }]), null);
  // EL ORDEN DEL ALBUM ES DE LA MAS NUEVA A LA MAS VIEJA.
  chequear('la primera del mes es la ultima de la lista',
    A158.primeraYUltima([{ fecha: '2026-09-09' }, { fecha: '2026-09-01' }]),
    { primera: { fecha: '2026-09-01' }, ultima: { fecha: '2026-09-09' } });
  const alb158 = sinComentarios158(de158('movil', 'src', 'Album.tsx'));
  chequear('el album muestra la comparacion', /estilos\.comparar/.test(alb158), true);
  chequear('y los numeros del mes', /T\.album\.cuentaDelMes/.test(alb158), true);

  // ---- LA TARJETA DICE QUE ESTABAS HACIENDO ----
  //
  // "El cuadro de la pantalla de bloqueo hoy es solo un timer." Con el telefono
  // boca arriba en el banco, "2:58" dice cuando volver y nada sobre a que.
  const wid158 = de158('movil', 'targets', 'descanso', 'index.swift');
  chequear('la tarjeta dibuja el ejercicio', /queHacias\(context\)/.test(wid158), true);
  chequear('y por cual serie vas', /"Serie \\\(s\) de \\\(m\)"/.test(wid158), true);
  // SIN DATO, LA TARJETA DE SIEMPRE: nunca se queda sin su segunda linea.
  chequear('sin ejercicio queda la duracion',
    /queHacias\(context\) \?\? deLargo\(context\.attributes\.duracion\)/.test(wid158), true);
  // VA EN ContentState Y NO EN LOS ATRIBUTOS: los atributos no se pueden tocar
  // una vez encendida la actividad, y la actividad se REUSA entre series.
  const at158 = de158('movil', 'targets', 'descanso', 'AtributosDelDescanso.swift');
  const estado158 = at158.slice(at158.indexOf('struct ContentState'), at158.indexOf('var duracion'));
  for (const campo of ['var ejercicio: String', 'var serie: Int', 'var meta: Int']) {
    chequear('el estado lleva ' + campo, estado158.includes(campo), true);
  }
  // EL NOMBRE LO RESUELVE LA PANTALLA DEL BLOQUE, que es la unica con el
  // catalogo cargado; el hook de la sesion no conoce el catalogo y no tiene
  // por que. SOLO EL NOMBRE: la serie y la meta salen del descanso (la 165).
  const blo158 = sinComentarios158(de158('movil', 'src', 'Bloque.tsx'));
  chequear('el bloque anota como se llama cada ejercicio', /ponerNombres\(ejercicios\)/.test(blo158), true);
  chequear('y el descanso manda lo que el mismo lleva adentro',
    /mostrarDescanso\(d\.fin, d\.duracion, loQueSeHacia\(d\)\)/.test(de158('compartido', 'descanso.ts')), true);
  // EL TEST NO SE BORRA, SE INVIERTE (2/10). Aca decia "la serie va con el mas
  // uno" y exigia el texto "serie: estado.hechas + 1". Era cierto el 23/9; el
  // 25/9 el conteo paso a moverse ANTES del descanso (62c8cc5) y el mas uno
  // empezo a contar dos veces la misma serie: "serie 4 de 3" en la pantalla
  // bloqueada, una semana, con este test en verde. Comprobaba que el archivo
  // dijera lo que decia, no lo que le llegaba al telefono. La conducta esta en
  // la 165, ejecutada.
  chequear('la pantalla del bloque ya no anota la serie, ni con mas uno ni sin',
    [/hechas \+ 1/.test(blo158), /serie: estado\.hechas/.test(blo158), /ponerEnCurso/.test(blo158)],
    [false, false, false]);
}

console.log('\n159. El aviso del motor en Diagnostico, y la mano al polvo');
{
  const { readFileSync: leer159 } = await import('node:fs');
  const { join: unir159 } = await import('node:path');
  const R159 = unir159(import.meta.dirname, '..');
  const de159 = (...p) => leer159(unir159(R159, ...p), 'utf8');

  // ---- EL AVISO DEL MOTOR, AHORA TAMBIEN EN EL TELEFONO ----
  //
  // "El aviso del motor: tambien en Diagnostico."
  //
  // En la web lo dice /galeria: un cielo sin ningun cuerpo se ve igual este
  // apagado a proposito o roto, y sin el aviso las dos cosas son el mismo
  // pixel negro. En el telefono eso hace mas falta todavia: no hay consola, no
  // hay galeria, y Diagnostico es la unica pantalla que cuenta que esta
  // viendo la app.
  const est159 = de159('movil', 'src', 'estadoDelMotor.ts');
  const fon159 = de159('movil', 'src', 'FondoRaiz.tsx');
  const dia159 = de159('movil', 'src', 'ajustes', 'Diagnostico.tsx');

  // LOS CINCO ESTADOS SON LOS DEL TELEFONO, no los cuatro de la web. Dos de
  // los de alla —"equipo flojo" y "no hay WebGL"— no pueden pasar aca: el
  // equipo nunca se lee como flojo (FondoRaiz le pasa null a proposito) y el
  // contexto lo da expo-gl, que no es el navegador. Mostrarlos seria ofrecer
  // dos respuestas imposibles.
  for (const e of ['sin-pedido', 'apagado', 'arrancando', 'andando', 'no-arranco']) {
    chequear(`el motor puede estar "${e}"`, est159.includes(`'${e}'`), true);
  }
  // Se explica en el archivo, pero lo que importa es que no lo IMPORTE: los
  // cuatro motivos de la web son del navegador y dos no pueden pasar aca.
  chequear('y no se reusa porQueNoHayMotor, que es del navegador',
    /^import[^;]*fondo/m.test(est159), false);

  // QUIEN LO ESCRIBE: la raiz, en los tres momentos en que se sabe algo.
  chequear('la preferencia apagada se anota al leerla',
    /ponerEstadoDelMotor\(hayQue \? 'arrancando' : 'apagado'\)/.test(fon159), true);
  chequear('y el renderer vivo tambien',
    /ponerEstadoDelMotor\('andando'\)/.test(fon159), true);
  // ERA UN return MUDO: se pedia el fondo, el lienzo llegaba a existir, el
  // renderer salia nulo y la pantalla quedaba sin cuerpo sin decir nada. Es el
  // unico de los cinco que es un error de verdad.
  chequear('y el unico error de verdad deja de ser mudo',
    /ponerEstadoDelMotor\('no-arranco'\);\s*\n\s*return;/.test(fon159), true);

  // EL MAPA ES EXHAUSTIVO A PROPOSITO: con Record<EstadoDelMotor, string>,
  // agregar un estado y no contarlo aca no compila.
  chequear('Diagnostico los dice todos, y el tipo lo obliga',
    /Record<EstadoDelMotor, string>/.test(dia159), true);
  chequear('y la fila se lee al dibujar, no en cargar()',
    /\[T\.ajustes\.diagMotor, DICE_EL_MOTOR\[comoAnduvoElMotor\(\)\]\]/.test(dia159), true);

  // ---- LA MANO AL POLVO (rango 1) ----
  //
  // "El polvo/nebulosa: si, dale la mano."
  //
  // Es el rango 1: el fondo que ve TODO EL MUNDO los primeros diez dias, y el
  // unico cuerpo que no habia pasado por la misma revision que el sol, la
  // galaxia y el agujero negro. La critica es la misma que se le hizo a los
  // brazos de la galaxia: la densidad era un smoothstep sobre la turbulencia,
  // o sea una joroba, y una joroba no tiene forma.
  const sha159 = de159('compartido', 'motor', 'shaders.ts');
  const neb159 = sha159.slice(sha159.indexOf('NEBULOSA (modo 5)'), sha159.indexOf('AURORA (modo 4)'));

  // 1. VETAS. "1 - |2f-1|" vale 1 justo donde el ruido cruza la mitad y cae a
  //    los dos lados: dibuja la CURVA DE NIVEL del ruido como un filo fino en
  //    vez de rellenar su interior. Es el borde encendido del motor llevado a
  //    algo que no es una esfera.
  chequear('el gas se dibuja por vetas y no por manchas',
    /float veta = 1\.0 - abs\(fbm\([\s\S]*?\) \* 2\.0 - 1\.0\);/.test(neb159), true);
  chequear('y la veta se afina elevandola', /veta = pow\(clamp\(veta/.test(neb159), true);
  // 2. CALLES DE POLVO: franjas frias que TAPAN el gas de atras. En una
  //    nebulosa de verdad media mitad del dibujo no la hace lo que brilla,
  //    la hace lo que se interpone. Y arregla el apilado: el aditivo solo
  //    suma, asi que sin algo que reste todo termina blanco.
  chequear('hay calles de polvo que restan', /1\.0 - calle \* 0\.72/.test(neb159), true);
  // 3. UN ADENTRO Y UN AFUERA: el calido de la paleta solo llega donde el gas
  //    esta ionizado, o sea cerca del centro. Antes el color dependia solo del
  //    ruido y la nube no tenia centro.
  chequear('y un nucleo encendido que le da centro',
    /float nucleo = smoothstep\(0\.66, 0\.04/.test(neb159), true);
  chequear('el calido solo llega en el nucleo',
    /uPaleta3, pow\(densidad, 2\.0\) \* nucleo/.test(neb159), true);

  // NINGUN BACKTICK EN EL SHADER: vive dentro de un template literal de
  // TypeScript, asi que un acento invertido en un comentario GLSL corta la
  // cadena. Paso al escribir esto, y el error que da es de sintaxis a treinta
  // lineas de distancia.
  chequear('el bloque de la nebulosa no tiene backticks', neb159.includes('`'), false);
}

console.log('\n160. Barrido: la cuenta que ya no existe, los minutos, y el visor');
{
  const { readFileSync: leer160 } = await import('node:fs');
  const { join: unir160 } = await import('node:path');
  const R160 = unir160(import.meta.dirname, '..');
  const de160 = (...p) => leer160(unir160(R160, ...p), 'utf8');

  // ---- LA CUENTA QUE YA NO EXISTE ----
  //
  // Borrar la cuenta desde otro aparato deja este con un token que sigue
  // siendo valido —esta firmado y no vencio— pero que apunta a un usuario que
  // no esta. El telefono cree que hay sesion, pide el perfil, no viene
  // ninguna fila, y la pantalla dice "algo fallo, proba de nuevo" con un boton
  // de reintentar que no puede funcionar NUNCA. Encontrado el 25/9 rehaciendo
  // la cuenta de App Review con la app abierta.
  const { laCuentaYaNoExiste } = await import('../nucleo/errores.ts');

  chequear('403 del servidor: la cuenta se fue',
    laCuentaYaNoExiste({ status: 403, message: 'User from sub claim in JWT does not exist' }), true);
  chequear('401 tambien', laCuentaYaNoExiste({ status: 401, message: 'invalid claim' }), true);
  // LO QUE NO PUEDE PASAR, y es la mitad de por que esto es una funcion:
  // preguntarle al servidor quien sos falla IGUAL sin red. Cerrar la sesion
  // ahi seria echar de la app a alguien por estar en un subsuelo, que es media
  // app de gimnasio — y encima no podria volver a entrar hasta tener senal.
  chequear('sin red NO se concluye nada',
    laCuentaYaNoExiste({ status: 0, message: 'Failed to fetch' }), false);
  chequear('ni con un NetworkError',
    laCuentaYaNoExiste({ message: 'NetworkError when attempting to fetch resource' }), false);
  chequear('ni sin error', laCuentaYaNoExiste(null), false);
  // Un error sin status no vino del servidor.
  chequear('ni un error sin status', laCuentaYaNoExiste({ message: 'algo raro' }), false);

  const ini160 = de160('movil', 'src', 'Inicio.tsx');
  // maybeSingle y no single: que no haya fila NO es un error de la consulta,
  // es un dato, y hay que poder distinguirlo de que la consulta no llegara.
  chequear('el perfil se pide con maybeSingle',
    /from\('profiles'\)\.select\('\*'\)\.eq\('id', uid\)\.maybeSingle\(\)/.test(ini160), true);
  // EL signOut NO ES DE MAS: `alSalir` solo hace que la raiz vuelva a mirar la
  // sesion, y el token guardado sigue ahi. Sin esto la raiz lo encuentra otra
  // vez y vuelve a la misma pantalla rota.
  chequear('si la cuenta se fue, se cierra la sesion de verdad',
    /laCuentaYaNoExiste\(eQuien\)\) \{[\s\S]*?await supabase\.auth\.signOut\(\);[\s\S]*?return alSalir\(\);/.test(ini160), true);

  // ---- LOS MINUTOS DE HOY, DEL SERVIDOR ----
  //
  // "Desaparecio 'Dia registrado - hoy entrenaste X minutos'. Me gustaba que
  // apareciera el tiempo."
  //
  // Separarlo de `cierre` arreglaba cerrar la TARJETA; no arreglaba cerrar la
  // APP. El numero solo existia si esta misma pantalla habia visto terminar la
  // sesion, asi que volver a abrir Ascent a la noche lo dejaba en la nada
  // aunque la sesion estuviera guardada.
  // Desde el 21/10 la consulta vive en compartido/inicioAlArrancar.ts (la usa también el arranque).
  const deHoy160 = de160('compartido', 'inicioAlArrancar.ts');
  chequear('los minutos salen de las sesiones terminadas de hoy',
    /\.select\('inicio, fin, bloques, logs!inner\(fecha\)'\)/.test(deHoy160) && /\.eq\('estado', 'terminada'\)/.test(deHoy160) && /pedirSesionesDeHoy\(supabase, uid\)/.test(ini160), true);
  // Y TAMBIEN LOS BLOQUES (1.2/5.4): es lo que deja volver a ver el resumen de
  // hoy a un toque, aun despues de recargar. El resumen ya no se cierra solo:
  // se cierra con una equis, y 'Ver lo que hiciste hoy' lo reabre.
  chequear('trae los bloques de hoy para reabrir el resumen',
    /const \[bloquesDeHoy, setBloquesDeHoy\]/.test(ini160), true);
  chequear('el resumen se cierra con una equis explicita, no tocando en cualquier lado',
    /setCierre\(null\)/.test(ini160) && !/<Pressable style=\{estilos\.resumen\} onPress=\{\(\) => setCierre\(null\)\}/.test(ini160), true);
  // `!inner` y no un select suelto: sin eso PostgREST devuelve TODAS las
  // sesiones con `logs` en null para las que no casan, y la suma saldria de la
  // semana entera en vez del dia.
  chequear('y se filtran por el dia del log, no por la hora de inicio',
    /\.eq\('logs\.fecha', hoyISO\(\)\)/.test(deHoy160), true);
  // Cero se guarda como null: "hoy entrenaste 0 minutos" no es un dato.
  chequear('cero minutos no se dice',
    /setMinutosDeHoy\(minutos >= 1 \? Math\.round\(minutos\) : null\)/.test(ini160), true);

  // ---- EL VISOR, OPACO ----
  //
  // El 4% de transparencia no dejaba pasar atmosfera: dejaba pasar EL ALBUM
  // —el titulo, el mes, las miniaturas— de fantasma detras de la foto abierta.
  const alb160 = de160('movil', 'src', 'Album.tsx');
  chequear('el visor de la foto es opaco',
    /visor: \{ flex: 1, backgroundColor: C\.fondo,/.test(alb160), true);
  chequear('y ya no deja ver el album atras',
    /rgba\(5,6,10,0\.96\)/.test(alb160), false);
}

console.log('\n161. Pulido: lo que cuesta el fondo, y como medirlo en el telefono');
{
  const { readFileSync: leer161 } = await import('node:fs');
  const { join: unir161 } = await import('node:path');
  const R161 = unir161(import.meta.dirname, '..');
  const de161 = (...p) => leer161(unir161(R161, ...p), 'utf8');

  // ---- EL PISO ES EL FONDO ----
  //
  // Medido con `medir-cuadros-nativa.mjs` (Chromium, CPU frenada 4x): con el
  // fondo prendido, TODAS las transiciones dan lo mismo —deslizar 9,8 fps,
  // abrir una foto 11, y la app QUIETA 10,2—. Ese "y la app quieta" es la
  // respuesta: el costo no es de ninguna transicion. Con el fondo apagado las
  // mismas dan 45, 60 y 56.
  //
  // Y desde que el cuerpo esta en las cinco pestanas, ese piso se paga en las
  // cinco, para animar con todo detalle algo que esta detras de un vidrio
  // esmerilado.
  const esc161 = de161('compartido', 'motor', 'escena.ts');
  const fon161 = de161('movil', 'src', 'FondoRaiz.tsx');

  // NO ES UN TERCER CAMINO: es el escalon lento que ya existe en
  // `nucleo/quietud.ts`, pedido por otra razon. Una sola regla de cuantos
  // cuadros se dibujan, y vive en un lugar solo.
  chequear('tapado se traduce a "hace rato que nadie toca"',
    /const sinTocar = tapado \? ESPERA_LENTO_MS : ahora - ultimoToque;/.test(esc161), true);
  chequear('y el motor lo expone', /tapar: \(si: boolean\) => void;/.test(esc161), true);
  // Al destaparse hay que DESPERTAR: si no, volver a Inicio deja el cuerpo a
  // doce cuadros hasta que alguien toque la pantalla.
  chequear('destaparse despierta',
    /const tapar = \(si: boolean\) => \{[\s\S]*?if \(!si\) despertar\(\);/.test(esc161), true);

  // STATS AHORA BAJA LOS CUADROS, PERO RECIEN ASENTADO (item bateria). Antes el
  // umbral unico 0,85 dejaba a Stats a 60 cuadros detras de la pantalla mas
  // pesada: el mayor gasto del motor, y calor. Ahora hay dos umbrales: 0,85 tapa
  // AL TOQUE lo que se ve del todo (Ranking/Album/Ajustes), y 0,4 tapa a Stats
  // pero DESPUES de que el deslizamiento asienta (setTimeout), para no bajar los
  // cuadros a mitad de la transicion, que era la razon del 0,85.
  chequear('el umbral inmediato tapa lo que se ve del todo', /const TAPADO_INMEDIATO = 0\.85;/.test(fon161), true);
  chequear('un umbral mas bajo tapa a Stats', /const TAPADO_ASENTADO = 0\.4;/.test(fon161), true);
  chequear('Stats se tapa recien cuando el deslizamiento asienta',
    /setTimeout\(\(\) => aplicar\(true\), ASENTARSE_MS\)/.test(fon161), true);
  // LA ESCENA NACE SABIENDO si esta tapada: se monta dentro de una promesa, asi
  // que cuando corre el efecto puede no existir todavia.
  chequear('la escena recien montada ya sabe si esta tapada',
    /m\?\.tapar\(tapadoAhora\.current\);/.test(fon161), true);
  chequear('y la que se reusa tambien',
    /actual\.montaje\.tapar\(tapadoAhora\.current\);/.test(fon161), true);

  // ---- LAS ELIPSES NO SE VUELVEN A DIBUJAR ----
  //
  // Desde que el desenfoque sigue al dedo, un solo deslizamiento vuelve a
  // dibujar la raiz del fondo hasta catorce veces, y estas dos capas de SVG se
  // reconciliaban en cada una para dar exactamente el mismo resultado.
  const eli161 = de161('movil', 'src', 'ElipsesDeLuz.tsx');
  chequear('las elipses van memoizadas', /export default memo\(ElipsesDeLuz\);/.test(eli161), true);
  // LA COMPARACION POR OMISION ALCANZA SOLO SI LAS PROPS SON ESTABLES:
  // `paletaDe` devuelve el objeto de la tabla, no uno nuevo. Si alguna vez
  // pasara a armarlo en el render, el memo dejaria de servir sin avisar.
  const pal161 = de161('nucleo', 'paletas.ts');
  chequear('y paletaDe devuelve el mismo objeto, no uno nuevo',
    /return PALETAS_RANGO\[rango\] \?\? PALETAS_RANGO\[1\];/.test(pal161), true);

  // ---- EL MEDIDOR QUE CORRE EN EL TELEFONO ----
  //
  // Los scripts de medir corren Chromium con la CPU frenada y lo dicen ellos
  // mismos: son un piso, no una medicion. Y ahi las animaciones corren en JS,
  // mientras que en el telefono `useNativeDriver` las saca del hilo. Lo unico
  // que puede contestar la pregunta es el aparato.
  const med161 = de161('movil', 'src', 'medirCuadros.ts');
  const dia161 = de161('movil', 'src', 'ajustes', 'Diagnostico.tsx');
  // LOS TRES NUMEROS VAN JUNTOS: un segundo trabado repartido entre veinte
  // buenos da un promedio de 55 y se ve horrible. Lo que se siente es el peor.
  for (const campo of ['fps', 'peor', 'largos']) {
    chequear(`la medicion dice "${campo}"`, new RegExp(`${campo}:`).test(med161), true);
  }
  // NO DIBUJA MIENTRAS MIDE: un contador en pantalla seria un setState por
  // cuadro, o sea el medidor midiendose a si mismo.
  // SIN LOS COMENTARIOS: el propio archivo EXPLICA por que no hay un setState
  // por cuadro, y esa explicacion hacia fallar el chequeo.
  chequear('no hay setState por cuadro',
    /setState|useState/.test(med161.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*/g, '')), false);
  chequear('el resultado queda en la bitacora', /void anotar\(comoSeLlama, \{/.test(med161), true);
  chequear('y Diagnostico lo puede arrancar', /await medirCuadros\(\);/.test(dia161), true);

  // ---- Y DONDE CAYERON (26/9) ----
  //
  // La primera medicion en el telefono dio 57,3 cuadros por segundo, 16 largos
  // (1,4%) y el peor de 104 ms. Con eso no se decide nada: dieciseis largos
  // repartidos parejo en veinte segundos serian algo que pasa todo el tiempo;
  // los mismos dieciseis amontonados en los dos primeros son el arranque
  // —salir de Ajustes, Inicio pidiendo sus datos— y no hay nada que arreglar.
  chequear('se anota el segundo de cada largo', /cuando\.push\(/.test(med161), true);
  chequear('y cuantos fueron en el arranque',
    /const enElArranque = cuando\.filter\(\(s\) => s <= ARRANQUE_S\)\.length;/.test(med161), true);
  // NO SE DESCARTAN: esconder cuadros es la forma mas facil de mentir con una
  // medicion. Se cuentan aparte, que es otra cosa.
  chequear('los del arranque NO se descartan del total',
    /porcentajeLargos: cuadros > 1 \? Math\.round\(\(largos \/ \(cuadros - 1\)\)/.test(med161), true);
  chequear('y Diagnostico lo dice', /diagCuadrosArranque\(cuadros\.enElArranque, cuadros\.largos\)/.test(dia161), true);
}

console.log('\n162. La condicion del cuerpo es de la persona, no de la pantalla');
{
  const { readFileSync: leer162 } = await import('node:fs');
  const { join: unir162 } = await import('node:path');
  const R162 = unir162(import.meta.dirname, '..');
  const de162 = (...p) => leer162(unir162(R162, ...p), 'utf8');

  // QUE SE ROMPIA. Inicio pedia el fondo con cinco banderas —dia de descanso,
  // racha perdida, cuenta vacia, presagio y el fantasma del record— y las
  // otras SEIS pantallas pedian el mismo cuerpo sin ninguna. Esas banderas son
  // parte de la identidad de la escena (`claveDeEscena`), asi que en cualquier
  // dia en que alguna fuera cierta, salir de Inicio hacia CUALQUIER pestana
  // armaba la escena de nuevo: seis shaders y tres programas recompilados, a
  // mitad del deslizamiento.
  //
  // Y es el peor tipo de tiron: solo aparece algunos dias, asi que mirando la
  // app un martes cualquiera no esta.
  //
  // ESTO NO ES UN CHEQUEO DE TEXTO: se importa el modulo y se lo hace andar.
  // `pedidoDeFondo.ts` solo importa `createContext` de react y un TIPO del
  // motor, asi que corre en node tal cual.
  const { pedirFondo, soltarFondo, escucharFondo } = await import('../movil/src/pedidoDeFondo.ts');

  let visto = null;
  const dejarDeMirar = escucharFondo((p) => { visto = p; });

  // Un dia de descanso. Inicio es el unico que lo sabe —tiene los logs y los
  // descansos— y por eso es el unico que lo nombra.
  pedirFondo('inicio', {
    rango: 4, planeta: 'marte', esquina: 'abajo-derecha', atmosfera: true,
    reposo: true, apagado: false, vacio: false, presagio: false, fantasma: null,
  });
  chequear('Inicio nombra el reposo', visto?.reposo, true);

  // Cambiar de pestana: Inicio suelta, el album pide. Antes, el album pedia
  // sin `reposo` y la escena se armaba de nuevo.
  soltarFondo('inicio');
  pedirFondo('album', { rango: 4, planeta: 'marte', velo: 0.72 });
  chequear('el album hereda el reposo sin nombrarlo', visto?.reposo, true);
  // LO QUE LA PANTALLA SI ELIGE no se toca: el velo y la esquina son suyos, y
  // ademas no entran en la clave de la escena.
  chequear('y se queda con su velo', visto?.velo, 0.72);

  // LA PRUEBA DE QUE NO SE REARMA: la clave de la escena, que es la que decide
  // si hay que compilar shaders otra vez, sale igual de los dos lados.
  const { claveDeEscenaParaProbar } = await import('./clave-de-escena.mjs');
  const claveAlbum = claveDeEscenaParaProbar(visto);
  pedirFondo('inicio', {
    rango: 4, planeta: 'marte', esquina: 'arriba-derecha', atmosfera: true,
    reposo: true, apagado: false, vacio: false, presagio: false, fantasma: null,
  });
  chequear('la escena del album y la de Inicio son LA MISMA',
    claveDeEscenaParaProbar(visto), claveAlbum);

  // EL PERFIL DE UN AMIGO NO HEREDA: es el unico cuerpo que no es el tuyo, y
  // tu dia de descanso no tiene por que apagarle el planeta.
  pedirFondo('amigo', { rango: 6, planeta: null, velo: 0.72, ajeno: true });
  chequear('el perfil de un amigo no hereda tu reposo', visto?.reposo ?? null, null);
  chequear('y muestra SU rango', visto?.rango, 6);
  soltarFondo('amigo');
  soltarFondo('album');
  soltarFondo('inicio');
  dejarDeMirar();

  // ---- Y QUE SIGA SIENDO UNA SOLA PANTALLA LA QUE LAS NOMBRA ----
  //
  // La regla es "quien las nombra, las fija". Si manana otra pantalla nombra
  // una, le estaria fijando la condicion del cuerpo a toda la app sin saberlo.
  const PANTALLAS = ['Ranking', 'Stats', 'Ajustes', 'Album', 'PerfilPropio', 'MisMarcas', 'PerfilDeAmigo'];
  for (const p of PANTALLAS) {
    const src = de162('movil', 'src', `${p}.tsx`);
    const pedido = (src.match(/<FondoEspacial[\s\S]*?\/>/) ?? [''])[0];
    chequear(`${p} no nombra las banderas del cuerpo`,
      /(^|\s)(reposo|apagado|vacio|presagio|fantasma)=/.test(pedido), false);
  }
  const ini162 = de162('movil', 'src', 'Inicio.tsx');
  const pedidoInicio = (ini162.match(/<FondoEspacial[\s\S]*?\/>/) ?? [''])[0];
  for (const b of ['apagado', 'vacio', 'reposo', 'presagio', 'fantasma']) {
    chequear(`Inicio si nombra ${b}`, new RegExp(`(^|\\s)${b}=`).test(pedidoInicio), true);
  }
  // Y el de un amigo tiene que decir que es ajeno, o le pondriamos tu estado.
  const ami162 = de162('movil', 'src', 'PerfilDeAmigo.tsx');
  chequear('el perfil de un amigo se declara ajeno',
    /ajeno\s*\n?\s*\/>/.test((ami162.match(/<FondoEspacial[\s\S]*?\/>/) ?? [''])[0]), true);
}
{
  // LA COPIA DE LA CLAVE NO SE PUEDE SEPARAR DE LA DE VERDAD. Si alguien
  // agrega un campo alla y no aca, el chequeo de arriba dejaria de ver
  // rearmados que si ocurren, y en silencio.
  const { readFileSync: leer162b } = await import('node:fs');
  const { join: unir162b } = await import('node:path');
  const R162b = unir162b(import.meta.dirname, '..');
  const campos = (txt, desde) => {
    const i = txt.indexOf(desde);
    const cuerpo = txt.slice(i, txt.indexOf('].join(', i));
    return cuerpo
      .split('\n')
      .map((l) => l.replace(/\/\/.*/, '').trim())
      .filter((l) => l.endsWith(','))
      .map((l) => l.replace(/\s/g, ''));
  };
  const real = campos(
    leer162b(unir162b(R162b, 'movil', 'src', 'FondoRaiz.tsx'), 'utf8'),
    'function claveDeEscena('
  );
  const copia = campos(
    leer162b(unir162b(R162b, 'supabase', 'clave-de-escena.mjs'), 'utf8'),
    'export function claveDeEscenaParaProbar('
  );
  chequear('la copia de la clave de escena no se separo de la de verdad', copia, real);
}

console.log('\n163. Pantallas sin salida: la de elegir nombre');
{
  const { readFileSync: leer163 } = await import('node:fs');
  const { join: unir163 } = await import('node:path');
  const R163 = unir163(import.meta.dirname, '..');
  const de163 = (...p) => leer163(unir163(R163, ...p), 'utf8');

  // LA TERCERA DE LA MISMA FAMILIA. Las otras dos fueron el perfil sin senal
  // —una pantalla apilada cuya rama de error no dibujaba el "Volver"— y la
  // cuenta borrada desde otro aparato, que dejaba un "Reintentar" que no podia
  // funcionar nunca.
  //
  // Esta es peor que las dos: la pantalla de elegir nombre no tiene barra de
  // pestanas —la cuenta todavia no esta terminada— ni nada apilado abajo, asi
  // que el unico boton era "Empezar". Sin senal ese boton no puede hacer nada,
  // porque el nombre se guarda en la base. Y cerrar la app no ayudaba: al
  // volver hay sesion y sigue sin haber nombre, o sea que la raiz dibuja esta
  // misma pantalla otra vez.
  const onb = de163('movil', 'src', 'Onboarding.tsx');

  chequear('hay una salida', /function salir\(\)/.test(onb), true);
  // EL signOut VA PRIMERO y no alcanza con avisarle a la raiz: `alElegir` es
  // `mirar`, que vuelve a preguntar si hay sesion. Con la sesion todavia
  // guardada, la respuesta es que si y se vuelve a entrar a lo mismo.
  chequear('cierra la sesion antes de avisar',
    /await supabase\.auth\.signOut\(\)[\s\S]{0,60}alElegir\(\);/.test(onb), true);
  // SIN RED TAMBIEN, que es el caso en el que esto hace falta: el signOut
  // contra el servidor falla, pero la sesion local se borra igual, y la local
  // es la que mira la raiz.
  chequear('y sin red se sale igual', /signOut\(\)\.catch\(\(\) => \{\}\)/.test(onb), true);
  chequear('y esta en pantalla', /onPress=\{salir\}/.test(onb), true);

  // ---- Y LAS OTRAS DOS NO SE VUELVEN ATRAS ----
  for (const [p, que] of [
    ['PerfilPropio', 'el perfil propio'],
    ['PerfilDeAmigo', 'el perfil de un amigo'],
    ['MisMarcas', 'mis marcas'],
  ]) {
    const src = de163('movil', 'src', `${p}.tsx`);
    // El "Volver" tiene que estar FUERA de la rama feliz: en estas tres es una
    // constante que se dibuja en todas las ramas.
    // Desde el 12/10 "siempre" incluye haber llegado por un enlace: sección 202.
    chequear(`${que} se puede cerrar siempre`, /volverOInicio\(router\)/.test(src), true);
  }

  // Y los cuatro modales se pueden cerrar.
  for (const m of ['Descanso', 'Hoja', 'RachaSalvada', 'SubidaRango']) {
    const src = de163('movil', 'src', `${m}.tsx`);
    chequear(`el modal ${m} se puede cerrar`, /onRequestClose=/.test(src), true);
  }
}

console.log('\n165. La pantalla bloqueada dice la serie que se acaba de hacer');
{
  const { serieDelDescanso } = await import('../nucleo/bloques.ts');
  const N165 = await import('../compartido/enCurso.ts');
  const { readFileSync: leer165 } = await import('node:fs');
  const { join: unir165 } = await import('node:path');
  const R165 = unir165(import.meta.dirname, '..');
  const de165 = (...p) => sinComentarios(leer165(unir165(R165, ...p), 'utf8'));
  const entre165 = (texto, desde, hasta) => {
    const i = texto.indexOf(desde);
    return i < 0 ? '' : texto.slice(i, texto.indexOf(hasta, i + desde.length));
  };

  // EL BUG (1/10, del gimnasio): "Listo · Remo con mancuerna · serie 4 de 3".
  //
  // La pantalla del bloque anotaba la serie desde un efecto, con un mas uno que
  // suponia que el descanso arrancaba ANTES de sumar. El 25/9 el conteo paso a
  // moverse primero (commit 62c8cc5) y el mas uno quedo contando dos veces la
  // misma serie. Una semana asi, con un test en verde: el de la 158 exigia el
  // texto "serie: estado.hechas + 1", o sea que comprobaba que el archivo
  // coincidiera con el bug.
  //
  // Por eso aca la cuenta SE EJECUTA: es una funcion de nucleo/, y el caso es
  // el del gimnasio, sumando con la misma funcion que usa el boton.

  // ---- LA CONDUCTA ----
  let c165 = { series: 0, bloques: bloquesVacios('remo_mancuerna', 3) };
  c165 = sumarSerie(c165);
  chequear('terminada la 1a de 3, dice serie 1 de 3',
    serieDelDescanso(c165.bloques), { ejercicio: 'remo_mancuerna', serie: 1, meta: 3 });
  c165 = sumarSerie(sumarSerie(c165));
  chequear('terminada la 3a de 3, dice 3 y NO 4',
    serieDelDescanso(c165.bloques), { ejercicio: 'remo_mancuerna', serie: 3, meta: 3 });
  // EL PATRON VIEJO, AL LADO: el mas uno sobre el estado ya sumado. Es lo que
  // se veia en el telefono, y es lo que esta prueba no deja volver.
  chequear('el patron viejo (mas uno sobre lo ya sumado) decia 4 de 3', c165.bloques.hechas + 1, 4);
  // PASARSE DE LA META ES LEGITIMO (regla 1 de bloques.ts): la cuarta serie se
  // CUENTA. Lo que cambio el 8/10 es como se DICE: hasta entonces la tarjeta
  // decia "4 de 3", que el humano pidio que no se vea nunca. Ahora dice
  // "Serie 4" a secas (meta 0 = se omite). Ver `metaQueSeDice`.
  c165 = sumarSerie(c165);
  chequear('una cuarta serie de verdad se cuenta, y se dice sin la meta',
    serieDelDescanso(c165.bloques), { ejercicio: 'remo_mancuerna', serie: 4, meta: 0 });

  // ---- EL DESCANSO SUELTO: la que YA se hizo, no la que viene ----
  let s165 = { series: 0, bloques: bloquesVacios('remo_mancuerna', 3) };
  s165 = sumarSerie(sumarSerie(s165));
  chequear('descansar suelto con 2 hechas dice la 2, no la 3',
    serieDelDescanso(s165.bloques), { ejercicio: 'remo_mancuerna', serie: 2, meta: 3 });
  // Recien cerrado el bloque, lo ultimo que se hizo es la ultima serie del
  // bloque cerrado. Su meta no se guarda: va en 0 y la tarjeta dice "Serie 3".
  const cerrado165 = terminarBloque(sumarSerie(s165).bloques);
  chequear('recien cerrado el bloque: la ultima del bloque cerrado',
    serieDelDescanso(cerrado165), { ejercicio: 'remo_mancuerna', serie: 3, meta: 0 });
  chequear('y lo mismo con el ejercicio siguiente ya elegido',
    serieDelDescanso(cambiarEjercicio(cerrado165, 'press_banca')), { ejercicio: 'remo_mancuerna', serie: 3, meta: 0 });
  // CERO = NO HAY SERIE QUE DECIR, y el widget con cero no dibuja la linea.
  chequear('sin nada hecho no inventa una serie',
    serieDelDescanso(bloquesVacios('press_banca', 3)), { ejercicio: 'press_banca', serie: 0, meta: 0 });
  chequear('y el widget con cero no dibuja la linea',
    /guard s > 0 else \{ return nil \}/.test(leer165(unir165(R165, 'movil', 'targets', 'descanso', 'index.swift'), 'utf8')), true);

  // ---- EL CABLEADO: que el descanso reciba ESA cuenta, del estado ya sumado ----
  //
  // El hook no se puede cargar con node, asi que el orden se lee. Solo, esto
  // seria un proxy; va junto con la conducta de arriba, y con el detector
  // probado contra las dos formas del bug.
  const hook165 = de165('compartido', 'useSesion.ts');
  const mirar165 = (texto) => {
    const iSuma = texto.indexOf('sumarSerie(');
    const iDescanso = texto.indexOf('guardarDescanso(');
    return {
      sumaAntesDelDescanso: iSuma > -1 && iDescanso > iSuma,
      conLoYaSumado: /guardarDescanso\(seg, serieDelDescanso\(nc\.bloques\)\)/.test(texto),
    };
  };
  chequear('serieHecha suma primero y le pasa al descanso lo ya sumado',
    mirar165(entre165(hook165, 'async function serieHecha(', 'async function deshacerSerie(')),
    { sumaAntesDelDescanso: true, conLoYaSumado: true });
  // QUE EL DETECTOR SIRVA DE ALGO: las dos formas de volver a romperlo.
  chequear('con el descanso antes de la suma, salta',
    mirar165('const d = guardarDescanso(seg, serieDelDescanso(nc.bloques)); const nc = sumarSerie(x);').sumaAntesDelDescanso, false);
  chequear('y leyendo otra cosa que lo sumado, tambien',
    mirar165('const nc = sumarSerie(x); const d = guardarDescanso(seg, serieDelDescanso(bloquesRef.current));').conLoYaSumado, false);

  const suelto165 = entre165(hook165, 'async function descansarSuelto(', 'return {');
  chequear('el descanso suelto manda lo que ya se hizo',
    /guardarDescanso\(seg, serieDelDescanso\(bloquesRef\.current\)\)/.test(suelto165), true);
  chequear('y no suma nada', /sumarSerie\(/.test(suelto165), false);

  // ---- EL DESCANSO LLEVA ADENTRO LO QUE SE HACIA ----
  //
  // Antes lo releia de la pantalla cada vez: cambiar la duracion despues de
  // "Terminar serie" pisaba la tarjeta con el bloque siguiente, y al reabrir la
  // app se perdia. Ahora viaja congelado en el descanso guardado.
  const desc165 = de165('compartido', 'descanso.ts');
  chequear('guardarDescanso congela lo que recibe, sin tocarlo',
    /serie: hecho\.serie, meta: hecho\.meta/.test(desc165), true);
  chequear('nadie le suma nada en el camino',
    [/hecho\.serie \+/.test(desc165), /hechas \+ 1/.test(desc165), /serie \+ 1/.test(desc165)], [false, false, false]);
  chequear('cambiar la duracion arrastra lo que se hacia',
    /\{ \.\.\.vivo, fin: inicio \+ duracion \* 1000, duracion \}/.test(desc165), true);
  chequear('la pantalla bloqueada lee del descanso y no de la pantalla',
    /mostrarDescanso\(d\.fin, d\.duracion, loQueSeHacia\(d\)\)/.test(desc165), true);
  chequear('y el puerto nativo pasa la serie tal cual',
    /ctx\?\.serie \?\? 0/.test(de165('movil', 'src', 'plataforma', 'enVivo.ts')), true);

  // ---- DE LA PANTALLA DEL BLOQUE SALEN SOLO LOS NOMBRES ----
  const nom165 = de165('compartido', 'enCurso.ts');
  chequear('el modulo de los nombres no sabe de series ni de metas',
    [/serie/.test(nom165), /meta/.test(nom165), /hechas/.test(nom165)], [false, false, false]);
  chequear('sin catalogo no hay nombre', N165.nombreDe('press_banca'), null);
  N165.ponerNombres([{ id: 'press_banca', nombre: 'Press de banca' }]);
  chequear('con catalogo, el nombre de verdad', N165.nombreDe('press_banca'), 'Press de banca');
  chequear('sin ejercicio no hay nombre', N165.nombreDe(null), null);
  // Un catalogo que no llego (sin senal) no borra lo que ya se sabia.
  N165.ponerNombres([]);
  chequear('un catalogo vacio no borra los nombres', N165.nombreDe('press_banca'), 'Press de banca');
}

console.log('\n166. El peso se recuerda por ejercicio Y por modo');
{
  const B = await import('../nucleo/bloques.ts');
  const P = await import('../nucleo/pesoRecordado.ts');
  const CP = await import('../nucleo/campoPeso.ts');
  const { readFileSync: leer166 } = await import('node:fs');
  const { join: unir166 } = await import('node:path');
  const R166 = unir166(import.meta.dirname, '..');
  const de166 = (...p) => sinComentarios(leer166(unir166(R166, ...p), 'utf8'));
  const entre166 = (texto, desde, hasta) => {
    const i = texto.indexOf(desde);
    return i < 0 ? '' : texto.slice(i, texto.indexOf(hasta, i + desde.length));
  };

  // EL PEDIDO (1/10): "si un dia hago remo por mancuerna a 20 y otro dia el
  // mismo remo por maquina a 50, se pisan entre ellos". El peso se recuerda por
  // la combinacion ejercicio + modo, y al cambiar de modo el que se propone es
  // el ultimo de ESE modo.
  //
  // EL MODO DEL CATALOGO SE LE PREGUNTA A LA BASE, no se escribe de memoria.
  const cat166 = Object.fromEntries(
    (await db.query('select id, carga from ejercicios')).rows.map((f) => [f.id, f.carga])
  );
  chequear('el catalogo trae el modo de las zancadas', cat166.zancadas, 'par');
  const REMO = 'remo_mancuerna';

  // ---- NO SE PISAN: un peso por modo ----
  const historial166 = [
    { bloques: [{ ejercicio: REMO, series: 3, pesos: [50, 50, 50], carga: 'total' }] },
    { bloques: [{ ejercicio: REMO, series: 3, pesos: [20, 20, 22], carga: 'par' }] },
  ];
  const copia166 = P.pesosDelHistorial(historial166, cat166);
  chequear('el remo guarda un peso por modo', copia166[REMO], { total: 50, par: 22 });
  chequear('de cada bloque, la ULTIMA serie con peso',
    P.pesosDelHistorial([{ bloques: [{ ejercicio: REMO, series: 3, pesos: [20, 24, null], carga: 'par' }] }], cat166)[REMO],
    { par: 24 });
  chequear('la sesion mas nueva gana, y solo en su modo',
    P.pesosDelHistorial([...historial166, { bloques: [{ ejercicio: REMO, series: 1, pesos: [55], carga: 'total' }] }], cat166)[REMO],
    { total: 55, par: 22 });
  chequear('un bloque sin pesos no dice nada',
    P.pesosDelHistorial([{ bloques: [{ ejercicio: REMO, series: 3 }] }], cat166), {});
  chequear('y con peso corporal no hay numero que recordar',
    P.pesosDelHistorial([{ bloques: [{ ejercicio: REMO, series: 2, pesos: [10, 10], carga: 'corporal' }] }], cat166), {});
  chequear('basura no rompe nada',
    [P.pesosDelHistorial(null, cat166), P.pesosDelHistorial([null, 7, { bloques: 'x' }, { bloques: [null, { ejercicio: 3 }] }], cat166)],
    [{}, {}]);

  // ---- UN BLOQUE SIN MODO USA EL DEL CATALOGO, NO 'total' ----
  //
  // Desde la 38 todo bloque con pesos lleva su modo, así que casi no pasa. Hasta
  // la migración 70 la base lo leía como 'total' y el teléfono con el del
  // catálogo; ahora los dos igual, y se ve con el MISMO bloque.
  {
    const u = await nuevoUsuario();
    await comoUsuario(u);
    const s = (await db.query('select iniciar_sesion() as v')).rows[0].v;
    const id = s.id ?? (await db.query('select id from sesiones where user_id = $1 order by inicio desc limit 1', [u])).rows[0].id;
    // Directo a la tabla, como en la 82: fijar_bloques le pondria el modo.
    await db.query('update sesiones set bloques = $2::jsonb where id = $1',
      [id, JSON.stringify([{ ejercicio: 'zancadas', series: 2, pesos: [18, 18] }])]);
    // Cerrada: la que está corriendo no entra en lo que propone la base.
    await db.query("update sesiones set estado = 'terminada', fin = now() where id = $1", [id]);
    const enLaBase = (await db.query("select como_arranca('zancadas') as v")).rows[0].v;
    chequear('la base lo lee con el modo del catálogo', [enLaBase.carga, Number(enLaBase.peso)], ['par', 18]);
    const filas = (await db.query('select bloques from sesiones where user_id = $1 order by inicio', [u])).rows;
    chequear('el telefono lee ESE MISMO bloque con el modo del catalogo',
      P.pesosDelHistorial(filas, cat166).zancadas, { par: 18 });
    chequear('y sin catalogo no adivina: no lo cuenta como total', P.pesosDelHistorial(filas, {}), {});
  }

  // ---- CAMBIAR DE MODO CON EL BLOQUE VACIO: el peso sigue al modo ----
  const proponer166 = (e, modo) =>
    B.pesoAlCambiarDeModo(B.cambiarCarga(e, modo), P.ultimoPesoEnModo(B.cambiarCarga(e, modo), copia166, REMO, modo, cat166));
  const vacio166 = B.bloquesVacios(REMO, 3);
  let e166 = B.proponerPeso(B.cambiarCarga(vacio166, 'total'), P.ultimoPesoEnModo(vacio166, copia166, REMO, 'total', cat166));
  chequear('al arrancar en total propone 50, y lo marca como propuesta', [e166.peso, e166.pesoPropuesto], [50, true]);
  e166 = proponer166(e166, 'par');
  chequear('al pasar a por mancuerna propone 22, no 50', [e166.carga, e166.peso, e166.pesoPropuesto], ['par', 22, true]);
  e166 = proponer166(e166, 'total');
  chequear('y de vuelta en total, otra vez 50', [e166.carga, e166.peso], ['total', 50]);
  // SIN NADA RECORDADO EN ESE MODO, la propuesta vieja se va: dejar los 50 de
  // la maquina debajo de "un lado por vez" es proponer cualquier cosa.
  const sinRecuerdo166 = proponer166(e166, 'una');
  chequear('en un modo sin historia la propuesta se va',
    [sinRecuerdo166.carga, 'peso' in sinRecuerdo166, 'pesoPropuesto' in sinRecuerdo166], ['una', false, false]);
  const aCorporal166 = proponer166(e166, 'corporal');
  chequear('y con peso corporal tambien: no hay numero', ['peso' in aCorporal166, 'pesoPropuesto' in aCorporal166], [false, false]);

  // ---- LO ESCRITO A MANO NO SE PISA NUNCA ----
  //
  // "Perder lo que escribi es el peor resultado posible, peor que proponer mal."
  let mano166 = B.cambiarPeso(B.cambiarCarga(vacio166, 'total'), 35);
  chequear('un peso escrito no lleva marca', [mano166.peso, 'pesoPropuesto' in mano166], [35, false]);
  chequear('cambiar de modo no lo toca, aunque haya uno recordado', proponer166(mano166, 'par').peso, 35);
  chequear('ni lo borra cuando no hay ninguno', proponer166(mano166, 'una').peso, 35);
  chequear('ni al pasar a peso corporal', proponer166(mano166, 'corporal').peso, 35);
  chequear('una propuesta que llega tarde tampoco', B.proponerPeso(mano166, 50), mano166);
  // ESCRIBIR ENCIMA DE UNA PROPUESTA LA VUELVE DE LA PERSONA, aunque el numero
  // sea el mismo que la app habia puesto.
  const reescrito166 = B.cambiarPeso(e166, 50);
  chequear('reescribir el mismo numero propuesto le saca la marca', [reescrito166.peso, 'pesoPropuesto' in reescrito166], [50, false]);
  chequear('y ya no se pisa al cambiar de modo', proponer166(reescrito166, 'par').peso, 50);
  // ...y para eso el campo tiene que AVISAR cuando se teclea el mismo numero.
  // Antes no avisaba: confirmar lo que se ve no cambia el peso (la 100).
  chequear('teclear el mismo numero avisa', CP.hayQueAvisar(CP.confirmarCampo('50', 50, 'kg'), true), true);
  chequear('entrar y salir sin tocar no avisa', CP.hayQueAvisar(CP.confirmarCampo('50', 50, 'kg'), false), false);
  chequear('un numero distinto avisa siempre', CP.hayQueAvisar(CP.confirmarCampo('52,5', 50, 'kg'), false), true);
  chequear('teclear y dejar vacio un campo vacio no avisa', CP.hayQueAvisar(CP.confirmarCampo('', undefined, 'kg'), true), false);
  // Los pasos + y - son de la persona: salen por cambiarPeso.
  chequear('borrar el peso se lleva la marca', 'pesoPropuesto' in B.cambiarPeso(e166, null), false);

  // ---- CON SERIES HECHAS EL PESO NO CAMBIA ----
  //
  // Ahi cambiar el modo es "me equivoque de etiqueta", no "empiezo de nuevo".
  const conSeries166 = B.sumar(e166);
  chequear('contar una serie confirma la propuesta', [conSeries166.peso, 'pesoPropuesto' in conSeries166, conSeries166.pesos], [50, false, [50]]);
  const reetiquetado166 = proponer166(conSeries166, 'par');
  chequear('cambiar de modo con series hechas no toca el peso', [reetiquetado166.carga, reetiquetado166.peso, reetiquetado166.pesos], ['par', 50, [50]]);
  const sinPesoConSeries166 = B.sumar(B.cambiarCarga(vacio166, 'total'));
  chequear('ni le inventa uno a un bloque que venia sin peso', 'peso' in proponer166(sinPesoConSeries166, 'par'), false);

  // ---- LO DE HOY VA ANTES QUE EL HISTORIAL, y sigue a las correcciones ----
  let hoy166 = B.cambiarCarga(B.cambiarPeso(vacio166, 24), 'par');
  hoy166 = B.terminarBloque(B.sumar(B.sumar(hoy166)));
  chequear('lo que se hizo hoy gana sobre la copia', P.ultimoPesoEnModo(hoy166, copia166, REMO, 'par', cat166), 24);
  chequear('y no contamina el otro modo', P.ultimoPesoEnModo(hoy166, copia166, REMO, 'total', cat166), 50);
  // ---- DE LA ÚLTIMA SESIÓN, LO MÁS PESADO (13/10) ----
  // Los pesos BAJAN dentro de la sesión, que es lo que pasa en el gimnasio: con
  // pesos que suben, "la última serie" y "la más pesada" dan lo mismo y no se prueba nada.
  const baja166 = [
    { bloques: [{ ejercicio: REMO, series: 3, pesos: [70, 70, 65], carga: 'total' }] },
    { bloques: [
      { ejercicio: REMO, series: 3, pesos: [60, 55, 50], carga: 'total' },
      { ejercicio: 'press_banca', series: 1, pesos: [40], carga: 'total' },
      { ejercicio: REMO, series: 2, pesos: [45, 45], carga: 'total' },
    ] },
  ];
  const copiaBaja166 = P.pesosDelHistorial(baja166, cat166);
  chequear('del historial se propone lo más pesado de la ÚLTIMA sesión: ni su última serie, ni el tope de otra sesión', copiaBaja166[REMO], { total: 60 });
  chequear('y es el mismo número que la lista muestra al lado del ejercicio', P.maximosDelHistorial(baja166, cat166)[REMO], { peso: copiaBaja166[REMO].total, carga: 'total' });
  chequear('con el bloque vacío, eso es lo que va al campo', P.ultimoPesoEnModo(vacio166, copiaBaja166, REMO, 'total', cat166), 60);
  let bajaHoy166 = B.cambiarCarga(B.cambiarPeso(vacio166, 60), 'total');
  bajaHoy166 = B.terminarBloque(B.sumar(B.cambiarPeso(B.sumar(bajaHoy166), 50)));
  chequear('DENTRO de la sesión de hoy se sigue desde la última serie, no desde el tope', [bajaHoy166.cerrados[0].pesos, P.ultimoPesoEnModo(bajaHoy166, copiaBaja166, REMO, 'total', cat166)], [[60, 50], 50]);
  // "Esas no eran por mancuerna": se corrige la etiqueta del bloque cerrado, y
  // el recuerdo se corrige solo, porque sale de los bloques y no de una copia
  // que se fue sumando serie a serie.
  const corregido166 = B.corregirCarga(hoy166, 0, 'total');
  chequear('corregir la etiqueta mueve el recuerdo de modo',
    [P.ultimoPesoEnModo(corregido166, copia166, REMO, 'total', cat166), P.ultimoPesoEnModo(corregido166, copia166, REMO, 'par', cat166)],
    [24, 22]);
  // El bloque en curso con series tambien cuenta, y sin modo propio usa el del
  // catalogo (las zancadas son par).
  const zancadas166 = B.sumar(B.cambiarPeso(B.bloquesVacios('zancadas', 3), 16));
  chequear('el bloque en curso sin modo cuenta en el del catalogo',
    [P.ultimoPesoEnModo(zancadas166, {}, 'zancadas', 'par', cat166), P.ultimoPesoEnModo(zancadas166, {}, 'zancadas', 'total', cat166)],
    [16, null]);
  chequear('el modo que se ve en un bloque sin modo es el del catalogo', P.modoDelBloqueEnCurso(zancadas166, cat166), 'par');
  chequear('y sin catalogo no se sabe', P.modoDelBloqueEnCurso(zancadas166, {}), null);
  chequear('nunca se propone nada para peso corporal', P.ultimoPesoEnModo(hoy166, { [REMO]: { corporal: 10 } }, REMO, 'corporal', cat166), null);

  // ---- LA MARCA NO VIAJA A LA BASE NI ROMPE LA REGLA 4 ----
  chequear('proponer nada sobre un bloque sin peso no agrega ni una llave', B.proponerPeso(vacio166, null), vacio166);
  chequear('lo que se manda a la base no lleva la marca',
    B.paraGuardar(B.sumar(B.proponerPeso(B.cambiarCarga(vacio166, 'par'), 22))),
    [{ ejercicio: REMO, series: 1, pesos: [22], carga: 'par' }]);
  chequear('cambiar de ejercicio no arrastra la marca', 'pesoPropuesto' in B.cambiarEjercicio(e166, 'press_banca'), false);
  // Una cache de antes de esto trae pesos sin marca: cae del lado seguro.
  chequear('un peso sin marca (cache vieja) se trata como escrito',
    B.proponerPeso({ cerrados: [], ejercicio: REMO, meta: 3, hechas: 0, peso: 40 }, 50).peso, 40);

  // ---- LA COPIA DEL TELEFONO: lo guardado vuelve limpio ----
  chequear('lo que no tiene forma de peso por modo se descarta',
    P.leerPesosPorModo({ [REMO]: { par: 22, discos: 9, total: 'x', una: -3 }, otro: null, vacio: {} }),
    { [REMO]: { par: 22 } });
  chequear('y basura da vacio', [P.leerPesosPorModo(null), P.leerPesosPorModo([1]), P.leerPesosPorModo('x')], [{}, {}, {}]);
  chequear('los modos del catalogo tambien se filtran',
    P.leerModosDelCatalogo({ a: 'par', b: 'discos', c: null }), { a: 'par' });

  // ---- EL CABLEADO (se lee: el hook no se puede cargar con node) ----
  const hook166 = de166('compartido', 'useSesion.ts');
  const cambio166 = entre166(hook166, 'async function elegirCarga(', 'async function corregirCargaDeBloque(');
  chequear('cambiar de modo pasa por la regla probada arriba',
    /pesoAlCambiarDeModo\(conModo, ultimoPesoEnModo\(conModo, sabido\.pesos, id, c, sabido\.catalogo\)\)/.test(cambio166), true);
  const propone166 = entre166(hook166, 'async function proponerElPesoDe(', 'async function proponerCargaYPeso(');
  // Desde el 10/10 lo que entra puede ser el recordado con un disco más (sección 198).
  chequear('las propuestas entran por proponerPeso', /const b = proponerPeso\(actual, subido \?\? recordado\)/.test(propone166), true);
  chequear('y solo con el bloque vacio', /actual\.hechas > 0\) return/.test(propone166), true);
  // UN PESO ESCRITO SE ESCRIBE EN UN SOLO LUGAR. Si una propuesta entrara por
  // cambiarPeso quedaria sin marca, o sea como escrita por la persona, y a
  // partir de ahi no se podria reemplazar nunca mas.
  chequear('cambiarPeso se llama solo desde elegirPeso', (hook166.match(/cambiarPeso\(/g) ?? []).length, 1);
  chequear('y es el de la persona',
    /cambiarPeso\(bloquesRef\.current, kg\)/.test(entre166(hook166, 'async function elegirPeso(', 'async function corregirPesoDeSerie(')), true);
  const arranque166 = entre166(hook166, 'async function proponerCargaYPeso(', 'function aplicarCargaSabida(');
  chequear('al elegir el ejercicio el peso sale del mismo camino', (arranque166.match(/proponerElPesoDe\(/g) ?? []).length, 2);
  chequear('y ya no se escribe directo el de como_arranca', /cambiarPeso|Number\(r\.peso\)/.test(arranque166), false);

  // LA COPIA ES DE UNA CUENTA y sale del historial, sin la sesion que corre:
  // lo de hoy esta en el telefono, mas al dia que la base.
  const copiaTs166 = de166('compartido', 'pesosRecordados.ts');
  chequear('la copia no se lee con otra cuenta', /g\?\.de === yo/.test(copiaTs166), true);
  chequear('el historial no incluye la sesion en curso', /\.neq\('estado', 'corriendo'\)/.test(copiaTs166), true);
  chequear('y un error de red devuelve la copia, no nada',
    /if \(sesiones\.error \|\| ejercicios\.error\) return leerRecordados\(\)/.test(copiaTs166), true);

  // EL CAMPO NO REESCRIBE LO QUE SE ESTA TECLEANDO. Una propuesta que llega
  // mientras la persona escribe cambiaba el peso desde afuera y el campo se
  // reescribia con ella: lo escrito se perdia sin haberse confirmado nunca.
  for (const [ruta, que] of [[['movil', 'src', 'CampoPeso.tsx'], 'nativa'], [['src', 'components', 'CampoPeso.tsx'], 'web']]) {
    const campo = de166(...ruta);
    chequear('el campo de la ' + que + ' no pisa lo que se esta tecleando', /if \(tecleando\.current\) return;\s*setTexto\(mostrar\(kg\)\)/.test(campo), true);
    chequear('y avisa cuando se teclea el mismo numero (' + que + ')', /hayQueAvisar\(r, tecleo && !compacto\)/.test(campo), true);
  }
}

console.log('\n167. Deslizar rapido: el gesto parte de la pestaña a la que va la tira');
{
  const D = await import('../nucleo/deslizar.ts');
  const { readFileSync: leer167 } = await import('node:fs');
  const { join: unir167 } = await import('node:path');
  const pes167 = sinComentarios(leer167(unir167(import.meta.dirname, '..', 'movil', 'src', 'Pestanas.tsx'), 'utf8'));
  const ANCHO = 390;
  const TOTAL = 5;

  // EL TITILEO AL DESLIZAR RAPIDO (3/10), el que sobrevivio a tres arreglos.
  //
  // El gesto partia de la pestaña ACTIVA, que es estado de React y cambia recien
  // cuando el viaje termina (340 ms) y la pantalla se vuelve a dibujar. Un
  // segundo gesto en ese rato colocaba la tira en la pestaña de antes: se veia
  // la anterior un cuadro o dos, y despues la nueva. Medido: la tira iba de
  // -390 (Ranking) a -17 (Inicio) y a -414.
  //
  // Ahora el gesto parte del RUMBO —a donde va la tira—, que cambia al soltar.
  // La cuenta esta en nucleo/ para poder ejecutarla aca.

  // ---- LA CONDUCTA: dos gestos pegados ----
  let rumbo167 = 0; // Inicio
  rumbo167 = D.alSoltar(rumbo167, -190, ANCHO, -0.9, TOTAL);
  chequear('al soltar el primer gesto el rumbo YA es Ranking', rumbo167, 1);
  chequear('y la tira viaja a su lugar', D.reposo(rumbo167, ANCHO), -390);
  // EL SEGUNDO GESTO EMPIEZA ANTES DE QUE EL VIAJE TERMINE: entre soltar y
  // volver a arrastrar no pasa nada mas, y la cuenta ya tiene que dar bien.
  chequear('el segundo gesto arrastra desde Ranking, y asoma el Album',
    D.arrastre(rumbo167, -24, ANCHO, TOTAL), { asoma: 2, x: -414 });
  // EL PATRON VIEJO, AL LADO: con la pestaña de antes, la misma cuenta manda la
  // tira de vuelta a Inicio. Ese era el cuadro que se veia.
  chequear('el patron viejo (la pestaña de antes) devolvia la tira a Inicio',
    D.arrastre(0, -24, ANCHO, TOTAL), { asoma: 1, x: -24 });
  rumbo167 = D.alSoltar(rumbo167, -190, ANCHO, -0.9, TOTAL);
  chequear('dos gestos pegados avanzan dos pestañas', rumbo167, 2);

  // ---- las reglas de siempre siguen valiendo por este camino ----
  chequear('un gesto corto y lento no cambia el rumbo', D.alSoltar(2, -40, ANCHO, -0.1, TOTAL), 2);
  chequear('uno corto pero rapido si', D.alSoltar(2, -40, ANCHO, -0.5, TOTAL), 3);
  chequear('hacia la derecha se vuelve a la anterior', D.alSoltar(2, 190, ANCHO, 0.9, TOTAL), 1);
  chequear('en los bordes no hay a donde ir',
    [D.alSoltar(0, 190, ANCHO, 0.9, TOTAL), D.alSoltar(4, -190, ANCHO, -0.9, TOTAL)], [0, 4]);
  chequear('y contra el borde la tira cede un cuarto del dedo', D.arrastre(0, 100, ANCHO, TOTAL), { asoma: null, x: 25 });
  chequear('cada pestaña descansa un ancho mas a la izquierda',
    [0, 1, 2, 3, 4].map((i) => D.reposo(i, ANCHO)), [0, -390, -780, -1170, -1560]);
  chequear('Inicio descansa en cero, sin signo', Object.is(D.reposo(0, ANCHO), 0), true);

  // ---- EL CABLEADO (se lee: un .tsx no se puede cargar con node) ----
  //
  // Solo, esto seria un proxy. Va junto con la conducta de arriba y con la
  // sonda que lo mide en la pantalla, con el procesador frenado
  // (herramientas/probar-deslizar-nativa.mjs, pasos 5 y 6).
  const gesto167 = (texto) => {
    const i = texto.indexOf('PanResponder.create({');
    const cuerpo = i < 0 ? '' : texto.slice(i, texto.indexOf('const dibujar', i));
    const iRumbo = cuerpo.indexOf('rumbo.current = ORDEN[hasta]');
    return {
      parteDelRumbo:
        /arrastre\(ORDEN\.indexOf\(rumbo\.current\)/.test(cuerpo) && /alSoltar\(ORDEN\.indexOf\(rumbo\.current\)/.test(cuerpo),
      noMiraLaActiva: cuerpo !== '' && !bordeDePalabra('pestana').test(cuerpo) && !/enReposo/.test(cuerpo),
      elRumboCambiaAntesDelViaje: iRumbo > -1 && iRumbo < cuerpo.indexOf('Animated.timing('),
      unViajeCortadoNoDecide: /\.start\(\(\{ finished \}\) => \{\s*if \(!finished\) return;/.test(cuerpo),
      noSeRearmaConLaPestana: /\[ancho, correr\]\s*\);/.test(cuerpo),
    };
  };
  chequear('el gesto parte del rumbo, lo cambia al soltar, y un viaje cortado no decide', gesto167(pes167), {
    parteDelRumbo: true,
    noMiraLaActiva: true,
    elRumboCambiaAntesDelViaje: true,
    unViajeCortadoNoDecide: true,
    noSeRearmaConLaPestana: true,
  });
  // QUE EL DETECTOR SIRVA DE ALGO: el gesto como estaba antes del arreglo.
  const viejo167 =
    'PanResponder.create({ onPanResponderMove: (_e, g) => { ' +
    'const destino = vecina(ORDEN.indexOf(pestana), g.dx, ORDEN.length); correr.setValue(enReposo + g.dx); }, ' +
    'onPanResponderRelease: (_e, g) => { Animated.timing(correr, {}).start(() => { if (viaja && destino) setPestana(destino); }); } }), ' +
    '[pestana, ancho, correr, enReposo] ); const dibujar';
  chequear('el gesto de antes no pasa ninguna', gesto167(viejo167), {
    parteDelRumbo: false,
    noMiraLaActiva: false,
    elRumboCambiaAntesDelViaje: false,
    unViajeCortadoNoDecide: false,
    noSeRearmaConLaPestana: false,
  });

  // LA BARRA: tocar una pestaña durante el viaje. El viaje cortado pisaba la
  // pestaña recien elegida: la barra marcaba una y se veia otra.
  const iIrA167 = pes167.indexOf('const irA = useCallback(');
  const irA167 = pes167.slice(iIrA167, pes167.indexOf('eventos.escuchar(IR_A_PESTANA', iIrA167));
  const iRumboBarra167 = irA167.indexOf('rumbo.current = destino;');
  chequear('la barra compara contra el rumbo', /if \(destino === rumbo\.current\) return;/.test(irA167), true);
  chequear('y lo cambia antes de mover la tira', iRumboBarra167 > -1 && iRumboBarra167 < irA167.indexOf('Animated.timing('), true);
  chequear('sin depender de la pestaña que se esta dibujando', /\[ancho, correr\]/.test(irA167) && !/\[pestana/.test(irA167), true);
}

console.log('\n168. El guardian de la OTA: EAS corre adentro de movil, con la CLI fija, y el error se ve');
{
  const H = await import('./huella.mjs');
  const { readFileSync: leer168 } = await import('node:fs');
  const { join: unir168, isAbsolute: entera168, basename: nombre168 } = await import('node:path');
  const { tmpdir: temporal168 } = await import('node:os');

  // LO QUE PASO (3/10). Al publicar, el guardian dijo "No pude consultar EAS
  // (Command failed: npx eas-cli build:list...)" y nada mas. La causa estaba en
  // el log de npm: npx sin version le pregunta al registro en cada corrida, y
  // esa consulta fallo por un archivo que faltaba en la cache de npm. EAS nunca
  // llego a correr. Al repetir el comando a mano DESDE LA RAIZ, eas-cli contesto
  // "EAS project not configured": otro error, por la carpeta, que parecia la
  // causa y no lo era. El guardian ya corria EAS adentro de movil.

  // ---- DESDE CUALQUIER CARPETA: se cambia de carpeta de verdad ----
  const aca168 = process.cwd();
  const desdeAca = H.llamadaAEas(['build:list']);
  let desdeOtra;
  try {
    process.chdir(temporal168());
    desdeOtra = H.llamadaAEas(['build:list']);
  } finally {
    process.chdir(aca168);
  }
  chequear('EAS corre en la misma carpeta se llame desde donde se llame', desdeOtra.opciones.cwd, desdeAca.opciones.cwd);
  chequear('esa carpeta es movil, con la ruta entera',
    [entera168(desdeAca.opciones.cwd), nombre168(desdeAca.opciones.cwd)], [true, 'movil']);
  // Y ES DONDE ESTA EL PROYECTO. El id se lee, no se escribe: eas init no se
  // corre nunca desde un script.
  let app168 = null;
  try {
    app168 = JSON.parse(leer168(unir168(desdeAca.opciones.cwd, 'app.json'), 'utf8'));
  } catch {
    // sin app.json ahi, la comprobacion de abajo falla sola
  }
  chequear('ahi esta el proyecto de EAS, con su id', /^[0-9a-f-]{36}$/.test(app168?.expo?.extra?.eas?.projectId ?? ''), true);

  // ---- LA CLI FIJA, y sin preguntarle nada al registro ----
  chequear('la CLI va con la version escrita', /^eas-cli@\d+\.\d+\.\d+$/.test(H.EAS_CLI), true);
  chequear('npx usa la ya bajada y no pregunta', desdeAca.args, ['--prefer-offline', '--yes', H.EAS_CLI, 'build:list']);

  // ---- CUANDO FALLA, SE VE LO QUE CONTESTO ----
  // El error como lo arma execFileSync: la primera linea y, debajo, la salida.
  const falla168 = new Error(
    'Command failed: npx eas-cli build:list --json\n' +
      'npm error code ENOENT\n' +
      'npm error enoent Invalid response body while trying to fetch https://registry.npmjs.org/eas-cli\n\n'
  );
  const dicho168 = H.loQueContesto(falla168).split('\n');
  chequear('la primera linea dice que comando fallo', dicho168[0], 'Command failed: npx eas-cli build:list --json');
  chequear('y debajo va el motivo de verdad', dicho168.slice(1), [
    'npm error code ENOENT',
    'npm error enoent Invalid response body while trying to fetch https://registry.npmjs.org/eas-cli',
  ]);
  // EL PATRON VIEJO, AL LADO: solo la primera linea. Con eso no se sabia nada.
  chequear('el patron viejo se quedaba sin el motivo', /ENOENT/.test(String(falla168.message).split('\n')[0]), false);
  chequear('una salida larga se recorta a lo ultimo', H.loQueContesto(new Error(['a', ...Array.from({ length: 30 }, (_, i) => 'l' + i)].join('\n'))).split('\n').length, 9);
  chequear('y algo que no es un error no rompe', H.loQueContesto(undefined).length > 0, true);

  // ---- EL CABLEADO: nadie llama a EAS por su cuenta ----
  const hue168 = sinComentarios(leer168(unir168(import.meta.dirname, 'huella.mjs'), 'utf8'));
  const pub168 = sinComentarios(leer168(unir168(import.meta.dirname, 'publicar-ota.mjs'), 'utf8'));
  chequear('leer las builds pasa por la llamada unica', /llamadaAEas\(\['build:list'/.test(hue168), true);
  chequear('publicar tambien', /llamadaAEas\(\['update'/.test(pub168), true);
  chequear('y ninguno nombra a la CLI por otro lado', [/eas-cli/.test(pub168), (hue168.match(/eas-cli@/g) ?? []).length], [false, 1]);
  chequear('el guardian muestra lo que contesto', /motivo\.split\('\\n'\)/.test(pub168) && /loQueContesto\(e\)/.test(hue168), true);
  // LEER SE REINTENTA UNA VEZ; PUBLICAR, NUNCA: publicar dos veces no es gratis.
  // Dos llamadas: exportar y subir. Ninguna se reintenta.
  chequear('exportar y subir se llaman una sola vez cada uno, sin reintento', (pub168.match(/execFileSync\(/g) ?? []).length, 2);

  // ---- LA OTA SE ARMA CON LAS VARIABLES DE LA BUILD DE SU CANAL (6/10) ----
  // La de `telefono` salía sin EXPO_PUBLIC_DIAGNOSTICO y le borraba Diagnóstico
  // al teléfono. Y a `store` no le puede llegar ni estando suelta en la terminal.
  const suelta = { PATH: 'x', EXPO_PUBLIC_DIAGNOSTICO: '1', EXPO_PUBLIC_MINIMO: '1' };
  chequear('la OTA a telefono lleva el diagnostico; la de store, nunca', [
    H.entornoDeLaOta('telefono', { PATH: 'x' }).EXPO_PUBLIC_DIAGNOSTICO,
    H.entornoDeLaOta('store', suelta).EXPO_PUBLIC_DIAGNOSTICO,
    H.entornoDeLaOta('store', suelta).EXPO_PUBLIC_MINIMO,
    H.entornoDeLaOta('telefono', suelta).EXPO_PUBLIC_MINIMO,
    H.entornoDeLaOta('store', suelta).PATH,
  ], ['1', undefined, undefined, undefined, 'x']);
  chequear('y el guardian exporta con ese entorno', /execFileSync\(exportar\.comando, exportar\.args, \{ \.\.\.exportar\.opciones, env: entornoDeLaOta\(canal\), stdio: 'inherit' \}\)/.test(pub168), true);

  // ---- EL PAQUETE EXPORTADO, CONTRA LO QUE DECLARA EL PERFIL (7/10) ----
  //
  // LA REGLA: una publicación se comprueba mirando el ARTEFACTO, nunca el
  // comando que lo arma. La prueba de arriba pasaba y la OTA salió sin la
  // variable igual: la caché del empaquetador reusó el archivo de antes. Acá se
  // arman paquetes de mentira con los sellos adentro —los de verdad se vieron
  // exportando a mano, con y sin la variable y con la caché de antes— y se mira
  // qué deja pasar el guardián.
  const { mkdtempSync, mkdirSync: carpeta168, writeFileSync: escribir168, rmSync } = await import('node:fs');
  const { tmpdir } = await import('node:os');
  const paquete = (sellos) => {
    const dist = mkdtempSync(unir168(tmpdir(), 'ascent-dist-'));
    for (const [plataforma, textos] of Object.entries(sellos)) {
      carpeta168(unir168(dist, '_expo', 'static', 'js', plataforma), { recursive: true });
      // Como en el paquete de verdad: los textos van pegados, entre bytes sueltos.
      escribir168(unir168(dist, '_expo', 'static', 'js', plataforma, 'index-abc.hbc'), Buffer.from('\u0000\u0001basura' + textos.join('') + 'tate\u0000', 'latin1'));
    }
    return dist;
  };
  const CON = 'ascent-sello:EXPO_PUBLIC_DIAGNOSTICO=1;';
  const SIN = 'ascent-sello:EXPO_PUBLIC_DIAGNOSTICO=no;';
  const MIN_NO = 'ascent-sello:EXPO_PUBLIC_MINIMO=no;';
  const MIN_SI = 'ascent-sello:EXPO_PUBLIC_MINIMO=1;';
  const revisar = (canal, sellos) => {
    const dist = paquete(sellos);
    try {
      return H.revisarPaquete(canal, dist).length;
    } finally {
      rmSync(dist, { recursive: true, force: true });
    }
  };
  const deTelefono = { ios: [CON, MIN_NO], android: [CON, MIN_NO] };
  const deTienda = { ios: [SIN, MIN_NO], android: [SIN, MIN_NO] };
  chequear('cada canal acepta SU paquete', [revisar('telefono', deTelefono), revisar('store', deTienda), revisar('minimo', { ios: [CON, MIN_SI], android: [CON, MIN_SI] })], [0, 0, 0]);
  // Lo del 7/10: la caché dejó afuera la variable, o la dejó adentro.
  chequear('a telefono no sube un paquete sin Diagnóstico', revisar('telefono', deTienda) > 0, true);
  chequear('a store no sube un paquete CON Diagnóstico', revisar('store', deTelefono) > 0, true);
  chequear('ni uno que lo traiga en una sola plataforma', revisar('store', { ios: [SIN, MIN_NO], android: [CON, MIN_NO] }) > 0, true);
  chequear('ni otra variable de otro perfil', revisar('store', { ios: [SIN, MIN_SI], android: [SIN, MIN_SI] }) > 0, true);
  chequear('ni uno con los dos sellos a la vez', revisar('store', { ios: [SIN, CON, MIN_NO], android: [SIN, MIN_NO] }) > 0, true);
  // Sin sello no se pudo comprobar: tampoco se sube.
  chequear('un paquete sin sello no se sube', [revisar('store', { ios: [], android: [] }) > 0, revisar('telefono', { ios: [CON, MIN_NO] }) > 0], [true, true]);
  // CADA VARIABLE DE CADA PERFIL TIENE SU SELLO. Si se agrega una a `eas.json`
  // y no a `sello.ts`, el guardián no tendría qué buscar: esto falla antes.
  const selloTs = leer168(unir168(import.meta.dirname, '..', 'movil', 'src', 'sello.ts'), 'utf8');
  const easJson = JSON.parse(leer168(unir168(import.meta.dirname, '..', 'movil', 'eas.json'), 'utf8'));
  const sinSello = Object.keys(easJson.build).flatMap((canal) =>
    H.sellosEsperados(canal).flatMap((s) => [s.tiene, ...s.noTiene]).filter((texto) => !selloTs.includes(`'${texto}'`))
  );
  chequear('toda variable de todo perfil de eas.json tiene su sello en sello.ts', [...new Set(sinSello)], []);
  chequear('y el sello se usa al arrancar: si nadie lo importa, no viaja en el paquete', /anotar\(SELLOS\.join\(' '\)\);/.test(leer168(unir168(import.meta.dirname, '..', 'movil', 'app', '_layout.tsx'), 'utf8')), true);
  chequear('el guardian exporta con la cache limpia, mira el paquete, y sube ESE', [
    H.llamadaAExportar().args.includes('--clear'),
    /const problemas = revisarPaquete\(canal\);\s*if \(problemas\.length > 0\) \{[\s\S]{0,260}process\.exit\(1\);/.test(pub168),
    /llamadaAEas\(\['update', '--channel', canal, '--message', mensajeArg, '--skip-bundler', '--input-dir', 'dist', '--non-interactive'\]\)/.test(pub168),
    pub168.indexOf('revisarPaquete(canal)') < pub168.indexOf("llamadaAEas(['update'"),
  ], [true, true, true, true]);
}

console.log('\n169. La luz de la barra sale de la posicion de la tira');
{
  const D = await import('../nucleo/deslizar.ts');
  const { readFileSync: leer169 } = await import('node:fs');
  const { join: unir169 } = await import('node:path');
  const pes169 = sinComentarios(leer169(unir169(import.meta.dirname, '..', 'movil', 'src', 'Pestanas.tsx'), 'utf8'));
  const ANCHO = 390;
  const TOTAL = 5;

  // LA LUZ TARDABA (3/10). Seguia a la pestaña activa, que es estado: al deslizar
  // llegaba 340 ms tarde, cuando terminaba el viaje, y ademas esperaba a que se
  // redibujaran todas las pantallas. Ahora es una opacidad que sale de DONDE
  // ESTA LA TIRA, con el mismo valor animado que mueve las pantallas.
  //
  // LA PROPIEDAD QUE SE CUIDA: no es un estado aparte, asi que no se puede
  // desincronizar de lo que se ve. Es la que falto cuando se rompio el titileo.

  // La misma cuenta que hace la interpolacion: por tramos, y fija en las puntas.
  const valor = (x, { entrada, salida }) => {
    if (x <= entrada[0]) return salida[0];
    for (let k = 1; k < entrada.length; k++) {
      if (x <= entrada[k]) {
        return salida[k - 1] + ((salida[k] - salida[k - 1]) * (x - entrada[k - 1])) / (entrada[k] - entrada[k - 1]);
      }
    }
    return salida[salida.length - 1];
  };
  const crudas = (x) => Array.from({ length: TOTAL }, (_, i) => valor(x, D.luzDePestana(i, TOTAL, ANCHO)));
  const luces = (x) => crudas(x).map((v) => Math.round(v * 100) / 100);

  // ---- EN REPOSO: una sola encendida, la de la pestaña donde esta la tira ----
  for (let i = 0; i < TOTAL; i++) {
    chequear('con la tira en la pestaña ' + i + ' se enciende solo esa',
      luces(D.reposo(i, ANCHO)), Array.from({ length: TOTAL }, (_, j) => (j === i ? 1 : 0)));
  }

  // ---- ACOMPAÑA AL DEDO: no espera a que se suelte ni a que termine el viaje ----
  chequear('a un cuarto del camino a Ranking: tres cuartos y un cuarto', luces(-97.5), [0.75, 0.25, 0, 0, 0]);
  chequear('a mitad de camino, las dos a medias', luces(-195), [0.5, 0.5, 0, 0, 0]);
  // EL SEGUNDO GESTO PEGADO, el del titileo: la tira en -414 es Ranking con el
  // Album asomando, y la luz dice exactamente eso sin que nadie le avise.
  chequear('con la tira pasando Ranking, la luz esta en Ranking', luces(-414), [0, 0.94, 0.06, 0, 0]);

  // ---- SIEMPRE HAY UNA LUZ ENTERA, repartida entre a lo sumo dos ----
  const sumas169 = new Set();
  const prendidas169 = new Set();
  for (let x = 0; x >= D.reposo(TOTAL - 1, ANCHO); x -= 13) {
    sumas169.add(Math.round(crudas(x).reduce((a, b) => a + b, 0) * 1e6) / 1e6);
    prendidas169.add(crudas(x).filter((v) => v > 0).length <= 2);
  }
  chequear('en todo el recorrido la luz suma siempre uno', [...sumas169], [1]);
  chequear('y nunca hay mas de dos prendidas a la vez', [...prendidas169], [true]);

  // ---- EN LOS BORDES NO SE APAGA: ahi la tira cede un poco ----
  chequear('tirando contra el borde, Inicio sigue entera', luces(D.arrastre(0, 100, ANCHO, TOTAL).x), [1, 0, 0, 0, 0]);
  chequear('y Ajustes tambien', luces(D.arrastre(TOTAL - 1, -100, ANCHO, TOTAL).x), [0, 0, 0, 0, 1]);

  // La interpolacion animada exige las posiciones en orden creciente; con un
  // ancho de cero —el primer dibujado— tres puntos iguales la romperian.
  chequear('las posiciones van siempre de menor a mayor, tambien con ancho cero',
    [ANCHO, 0].every((a) =>
      Array.from({ length: TOTAL }, (_, i) => D.luzDePestana(i, TOTAL, a).entrada).every((e) => e.every((v, k) => k === 0 || v > e[k - 1]))
    ), true);

  // ---- EL CABLEADO (se lee: un .tsx no se puede cargar con node) ----
  const barra169 = (texto) => {
    const i = texto.indexOf('accessibilityRole="tablist"');
    const barra = i < 0 ? '' : texto.slice(i, texto.indexOf('const estilos = StyleSheet.create(', i));
    return {
      laLuzEsUnaOpacidadDeLaTira:
        /opacity: luces\[i\]/.test(barra) &&
        /luzDePestana\(i, ORDEN\.length, ancho\)/.test(texto) &&
        /correr\.interpolate\(\{ inputRange: entrada, outputRange: salida, extrapolate: 'clamp' \}\)/.test(texto),
      // Ni el color ni la opacidad pueden volver a salir de la pestaña activa.
      noSaleDeLaPestanaActiva: barra !== '' && !/pestana === p (&&|\?)/.test(barra) && !/estilos\.activo/.test(barra),
    };
  };
  chequear('la luz de la barra es una opacidad atada a la tira, no a la pestaña activa', barra169(pes169), {
    laLuzEsUnaOpacidadDeLaTira: true,
    noSaleDeLaPestanaActiva: true,
  });
  // QUE EL DETECTOR SIRVA: la barra como estaba antes.
  chequear('la barra de antes no pasa', barra169(
    'accessibilityRole="tablist"> <Text style={[estilos.texto, pestana === p && estilos.activo]}>{T.nav[p]}</Text> const estilos = StyleSheet.create('
  ), { laLuzEsUnaOpacidadDeLaTira: false, noSaleDeLaPestanaActiva: false });
  // EL ROTULO ESTA DOS VECES (apagado y encendido): que no se lea dos veces.
  // Desde el 15/10 el rótulo pasa por `rotuloDe` (Ranking dice "Social" en la barra).
  chequear('cada pestaña lleva su nombre para el lector de pantalla', /: rotuloDe\(p\)\}/.test(pes169), true);
}

console.log('\n170. El día de racha que guarda cada log (migración 57)');
{
  const { readFileSync: leer170 } = await import('node:fs');
  const { join: unir170 } = await import('node:path');
  const mig57 = leer170(unir170(import.meta.dirname, 'migracion-57-dia-de-racha.sql'), 'utf8').replace(/\r\n/g, '\n');

  // ---- de acá en más: registrar anota el día ----
  const nuevo = await nuevoUsuario();
  await rachaDe(nuevo, 12, 1);
  await comoUsuario(nuevo);
  const reg = (await db.query(`select registrar_dia() as r`)).rows[0].r;
  chequear('registrar anota en el log la racha de ese día',
    (await db.query(`select racha_del_dia from logs where id = $1`, [reg.log_id])).rows[0].racha_del_dia, 13);

  // ---- EL RELLENO DE LOS DÍAS VIEJOS, que es lo que estaba mal (4/10) ----
  //
  // Se corre LA SENTENCIA DE LA MIGRACIÓN, sacada del archivo, sobre una
  // historia con una pérdida en el medio: doce días, uno faltado, y ocho más.
  // Al perder quedó en 2 (12 - 10), así que los ocho de después son del 3 al 10.
  const u = await nuevoUsuario();
  await rachaDe(u, 12, 9);
  await db.query(`update profiles set racha_actual = 2, racha_base = 2, perdida_fecha = mi_hoy() - 8 where id = $1`, [u]);
  await rachaDe(u, 8);
  chequear('la historia de la prueba: 12, se pierde, y 8 más = 10', (await perfil(u)).racha_actual, 10);

  // UN PLANETA DE ANTES, en un día anterior a la pérdida. Tocar una etiqueta
  // de un log no puede volver a calcular los planetas de ese día en adelante:
  // el disparador lo hacía con CUALQUIER update, y para los días de antes de la
  // pérdida la cuenta da "sin planeta", así que el relleno de la 57 —que toca
  // todos los logs— borraba los planetas de las rachas viejas.
  await db.query(`update logs set planeta_del_dia = 'Tierra' where user_id = $1 and fecha = mi_hoy() - 15`, [u]);
  const planetaViejo = async () =>
    (await db.query(`select planeta_del_dia from logs where user_id = $1 and fecha = mi_hoy() - 15`, [u])).rows[0].planeta_del_dia;
  chequear('escribirle el planeta a un log viejo no lo recalcula', await planetaViejo(), 'Tierra');

  // Como estaba la base antes de la 57: ningún log sabe su día.
  await db.query(`update logs set racha_del_dia = null where user_id = $1`, [u]);
  chequear('vaciar la etiqueta tampoco toca el planeta', await planetaViejo(), 'Tierra');

  const relleno = mig57.match(/\nupdate public\.logs[\s\S]*?;\n/);
  chequear('la migración 57 trae su relleno', relleno !== null, true);
  await db.exec(relleno[0]);

  const dias = (
    await db.query(`select mi_hoy() - fecha as hace, racha_del_dia from logs where user_id = $1 order by fecha`, [u])
  ).rows.map((x) => [Number(x.hace), x.racha_del_dia]);
  chequear('después de la pérdida, cada día lleva su número (con lo que quedó de antes)',
    dias.filter(([hace]) => hace <= 7), [[7, 3], [6, 4], [5, 5], [4, 6], [3, 7], [2, 8], [1, 9], [0, 10]]);
  // Qué día de racha era cada uno de los de ANTES de la pérdida ya no se puede
  // saber: se queda sin número. Un "día 0" inventado en la foto es peor que nada.
  chequear('antes de la pérdida no se inventa un número: queda vacío',
    [...new Set(dias.filter(([hace]) => hace > 7).map(([, dia]) => dia))], [null]);
  chequear('y el relleno no le borró el planeta al día viejo', await planetaViejo(), 'Tierra');
  chequear('ni movió la racha', (await perfil(u)).racha_actual, 10);

  // Correrla dos veces no cambia nada: solo rellena lo que está vacío.
  await db.exec(relleno[0]);
  chequear('correr el relleno de nuevo deja todo igual',
    (await db.query(`select array_agg(racha_del_dia order by fecha) as d from logs where user_id = $1 and fecha >= mi_hoy() - 7`, [u])).rows[0].d,
    [3, 4, 5, 6, 7, 8, 9, 10]);
}

console.log('\n171. Un día que entra antes de que nadie revise la pérdida (migración 59)');
{
  // LA RACHA QUE SE CAÍA A 1 (4/10). La pérdida —gastar una vida o restar 10—
  // la aplica `verificar_perdida`, que corre al abrir Inicio. Si el día de hoy
  // entraba ANTES de esa revisión, el disparador de los logs contaba hacia atrás
  // desde hoy, se topaba con el hueco de ayer y dejaba la racha en 1; y la
  // revisión, al llegar después, veía que hoy ya tenía día y no hacía nada. Ni
  // vida ni -10: cuarenta días perdidos por llegar al gimnasio con la app
  // cerrada.
  //
  // Se prueba POR LOS CAMINOS QUE ESCRIBEN el día sin pasar por Inicio, y lo que
  // se mira es lo que queda guardado: la racha, lo que quedó de antes, cuándo
  // fue la pérdida y cuántas vidas se gastaron.
  const estado = async (uid) => {
    const p = (
      await db.query(
        `select racha_actual, racha_base, mi_hoy() - perdida_fecha as perdio_hace,
                (select count(*)::int from vidas_usadas v where v.user_id = p.id and not v.devuelta) as vidas
           from profiles p where id = $1`,
        [uid]
      )
    ).rows[0];
    return { racha: p.racha_actual, base: p.racha_base, perdioHace: p.perdio_hace === null ? null : Number(p.perdio_hace), vidasUsadas: p.vidas };
  };
  const conAyerFaltado = async (dias = 40) => {
    const u = await nuevoUsuario();
    await rachaDe(u, dias, 2);
    return u;
  };
  const SIN_VIDAS = { racha: 31, base: 30, perdioHace: 1, vidasUsadas: 0 };
  const CON_VIDA = { racha: 41, base: 0, perdioHace: null, vidasUsadas: 1 };

  // ---- 1. LLEGAR AL GIMNASIO CON LA APP CERRADA: registrar_dia('ubicacion') ----
  await cuotaDeVidas(0);
  const a = await conAyerFaltado();
  await comoUsuario(a);
  const ra = (await db.query(`select registrar_dia('ubicacion') as r`)).rows[0].r;
  chequear('por ubicación y sin vidas: resta 10 y suma el día (40 → 31), no cae a 1', await estado(a), SIN_VIDAS);
  chequear('y la respuesta trae la racha que quedó', ra.racha, 31);
  chequear('revisar después no cobra de nuevo', [(await perder(a)).perdida, (await estado(a)).racha], [false, 31]);

  await cuotaDeVidas(2);
  const b = await conAyerFaltado();
  await comoUsuario(b);
  await db.query(`select registrar_dia('ubicacion')`);
  chequear('por ubicación y con vidas: se gasta una y la racha sigue (40 → 41)', await estado(b), CON_VIDA);

  // EL ORDEN NO PUEDE CAMBIAR EL RESULTADO: revisar primero y registrar después
  // —lo que pasa al abrir Inicio— tiene que dejar exactamente lo mismo.
  const c = await conAyerFaltado();
  await perder(c);
  await db.query(`select registrar_dia('manual')`);
  chequear('revisar primero y registrar después deja lo mismo', await estado(c), await estado(b));

  // ---- 2. MARCAR HOY DESDE EL CALENDARIO: un insert directo en logs ----
  const d = await conAyerFaltado();
  await db.query(`insert into logs (user_id, fecha) values ($1, mi_hoy())`, [d]);
  chequear('desde el calendario y con vidas: una vida y 41', await estado(d), CON_VIDA);

  await cuotaDeVidas(0);
  const e = await conAyerFaltado();
  await db.query(`insert into logs (user_id, fecha) values ($1, mi_hoy())`, [e]);
  chequear('desde el calendario y sin vidas: resta 10 y suma el día', await estado(e), SIN_VIDAS);

  // ---- 3. EMPEZAR LA SESIÓN (el vigilante al llegar) ----
  const f = await conAyerFaltado();
  await comoUsuario(f);
  await db.query(`select iniciar_sesion(null, 'ubicacion')`);
  chequear('empezar la sesión sin haber revisado: resta 10 y suma el día', await estado(f), SIN_VIDAS);

  // ---- 4. MARCAR HOY COMO DESCANSO A MANO, con ayer faltado ----
  // Un descanso no suma, pero tampoco puede esconder la falta de ayer: antes
  // dejaba la racha en 0.
  const g = await conAyerFaltado();
  await db.query(`insert into logs (user_id, fecha, es_descanso) values ($1, mi_hoy(), true)`, [g]);
  chequear('descanso a mano con ayer faltado: resta 10 y no suma', await estado(g), { racha: 30, base: 30, perdioHace: 1, vidasUsadas: 0 });

  // ---- 5. LA FALTA ES MÁS VIEJA QUE EL DÍA QUE ENTRA ----
  // Veinte días, anteayer faltado, y se anota AYER sin haber abierto Inicio.
  const h = await nuevoUsuario();
  await rachaDe(h, 20, 3);
  await db.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - 1)`, [h]);
  chequear('anotar ayer con anteayer faltado: resta 10 y suma el día (20 → 11)', await estado(h), { racha: 11, base: 10, perdioHace: 2, vidasUsadas: 0 });

  // ---- LO QUE NO TIENE QUE COBRAR NADA ----
  await cuotaDeVidas(2);
  // Corregir el día que faltaba ES tapar el hueco: ni vida ni -10.
  const i = await nuevoUsuario();
  await rachaDe(i, 10, 2);
  await db.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - 1)`, [i]);
  chequear('corregir "ayer sí fui" no gasta una vida ni resta', await estado(i), { racha: 11, base: 0, perdioHace: null, vidasUsadas: 0 });

  // Un día viejo, en el medio de la historia, no es "un día que entra".
  const j = await nuevoUsuario();
  await rachaDe(j, 10);
  await db.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - 20)`, [j]);
  chequear('anotar un día de hace tres semanas no toca la racha de hoy', await estado(j), { racha: 10, base: 0, perdioHace: null, vidasUsadas: 0 });

  // Y el caso de todos los días: sin huecos, registrar suma uno.
  const k = await nuevoUsuario();
  await rachaDe(k, 9, 1);
  await comoUsuario(k);
  await db.query(`select registrar_dia('ubicacion')`);
  chequear('sin huecos, registrar suma uno y nada más', await estado(k), { racha: 10, base: 0, perdioHace: null, vidasUsadas: 0 });

  // La cuenta de la pérdida "a tal día" no se llama desde el cliente: con ella
  // se le podría cobrar una pérdida a otra cuenta.
  const abiertas = (
    await db.query(
      `select p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public' and p.proname in ('aplicar_perdida_al', 'verificar_perdida_de')
          and (has_function_privilege('authenticated', p.oid, 'execute') or has_function_privilege('anon', p.oid, 'execute'))`
    )
  ).rows.map((x) => x.proname);
  chequear('ni la cuenta de la pérdida ni la revisión por id se pueden llamar desde el cliente', abiertas, []);

  await cuotaDeVidas(0);
}

console.log('\n172. La ruta de una foto tiene que ser de quien la anota (migración 60)');
{
  // EL AGUJERO (4/10). `photos` dejaba anotar una fila propia con la RUTA del
  // archivo de otro, y la regla del storage daba permiso con cualquier fila
  // visible de un amigo que tuviera esa ruta. Con dos cuentas amigas entre sí,
  // una anotaba la foto privada de un tercero como suya y la otra la bajaba.
  //
  // Se prueba el ataque entero. El storage de Supabase no existe en PGlite, así
  // que la tabla es de reemplazo; LAS REGLAS son las de schema.sql, sacadas del
  // archivo, que es lo que se está probando.
  const { readFileSync: leer172 } = await import('node:fs');
  const esquema172 = leer172(RUTA_SCHEMA, 'utf8').replace(/\r\n/g, '\n');
  const reglasDeStorage = esquema172.match(/create policy "fotos storage: [^"]+" on storage\.objects[\s\S]*?;\n/g) ?? [];
  chequear('schema.sql trae las dos reglas del storage de fotos', reglasDeStorage.length, 2);

  await db.exec(`
    create schema if not exists storage;
    create table storage.objects (bucket_id text not null, name text not null);
    create function storage.foldername(name text) returns text[] language sql immutable as $f$
      select (string_to_array(name, '/'))[1 : array_length(string_to_array(name, '/'), 1) - 1];
    $f$;
    alter table storage.objects enable row level security;
    grant usage on schema storage to authenticated;
    grant select on storage.objects to authenticated;
  `);
  for (const regla of reglasDeStorage) await db.exec(regla);

  const victima = await nuevoUsuario();
  const atacante = await nuevoUsuario();
  const complice = await nuevoUsuario();
  await db.query(`insert into friendships (solicitante, destinatario, estado) values ($1, $2, 'aceptada')`, [atacante, complice]);

  const privada = `${victima}/2026-10-04-123.jpg`;
  await db.query(`insert into storage.objects (bucket_id, name) values ('fotos', $1)`, [privada]);
  await db.query(`insert into photos (user_id, storage_path, visibilidad) values ($1, $2, 'privada')`, [victima, privada]);

  const como = async (uid, hacer) => {
    await comoUsuario(uid);
    await db.exec('set role authenticated');
    try {
      return await hacer();
    } finally {
      await db.exec('reset role');
    }
  };
  const entra = (uid, fila) =>
    como(uid, () =>
      db
        .query(`insert into photos (user_id, log_id, storage_path, visibilidad) values ($1, $2, $3, 'amigos')`, [uid, fila.log ?? null, fila.ruta])
        .then(() => true, () => false)
    );
  const archivosQueVe = (uid) =>
    como(uid, async () => (await db.query(`select name from storage.objects where bucket_id = 'fotos' order by name`)).rows.map((x) => x.name));

  chequear('antes de nada, el cómplice no ve la foto privada', await archivosQueVe(complice), []);

  // ---- 1. LA PUERTA DE ENTRADA: anotar como propia la ruta de otro ----
  chequear('no se puede anotar como propia la ruta del archivo de otro', await entra(atacante, { ruta: privada }), false);
  chequear('y el cómplice sigue sin verla', await archivosQueVe(complice), []);

  // ---- 2. Y SI LA FILA YA ESTABA (anotada antes del arreglo), TAMPOCO DA PERMISO ----
  await db.query(`insert into photos (user_id, storage_path, visibilidad) values ($1, $2, 'amigos')`, [atacante, privada]);
  chequear('una fila ajena que ya estaba no le abre el archivo al cómplice', await archivosQueVe(complice), []);

  // ---- 3. EL LOG TAMBIÉN: no se cuelga una foto del día de otro ----
  await comoUsuario(victima);
  const logAjeno = (await db.query(`select registrar_dia() as r`)).rows[0].r.log_id;
  chequear('no se puede colgar una foto del día de otro',
    await entra(atacante, { ruta: `${atacante}/2026-10-04-1.jpg`, log: logAjeno }), false);

  // ---- LO QUE TIENE QUE SEGUIR ANDANDO: la app de siempre ----
  await comoUsuario(atacante);
  const logPropio = (await db.query(`select registrar_dia() as r`)).rows[0].r.log_id;
  const propia = `${atacante}/2026-10-04-999.jpg`;
  await db.query(`insert into storage.objects (bucket_id, name) values ('fotos', $1)`, [propia]);
  chequear('una foto propia, en su carpeta y con su día, entra', await entra(atacante, { ruta: propia, log: logPropio }), true);
  chequear('y sin día también', await entra(atacante, { ruta: `${atacante}/2026-10-04-1000.jpg` }), true);
  chequear('el amigo ve la que le compartieron, y solo esa', await archivosQueVe(complice), [propia]);
  chequear('el dueño ve lo suyo', await archivosQueVe(victima), [privada]);
  chequear('y pasarla a privada sigue andando',
    await como(atacante, () =>
      db.query(`update photos set visibilidad = 'privada' where storage_path = $1 and user_id = $2`, [propia, atacante]).then(() => true, () => false)
    ), true);
  chequear('con lo que el amigo deja de verla', await archivosQueVe(complice), []);
}

console.log('\n173. La 59 y la 60 se pueden correr HOY, sobre el esquema 53, y otra vez en su lugar');
{
  // LO QUE SE PRUEBA ES EL ORDEN REAL. Producción está en el 53 con la 54 a la
  // 58 sin aplicar. La 59 (la racha que se caía a 1) y la 60 (la foto privada)
  // no dependen de ellas, y su cabecera dice que se pueden correr ya, sin subir
  // la versión, y de nuevo después de la 58. Eso no se deduce: se corre.
  //
  // La base de acá es la de producción: el schema.sql del commit anterior a la
  // migración 54, sacado de git como hace `test-deriva`.
  const { execFileSync } = await import('node:child_process');
  const { readFileSync: leer173, readdirSync } = await import('node:fs');
  const aqui = dirname(fileURLToPath(import.meta.url));
  const git = (...a) => execFileSync('git', a, { cwd: join(aqui, '..'), encoding: 'utf8', maxBuffer: 20 * 1024 * 1024 });
  const la54 = git('log', '--diff-filter=A', '--format=%H', '--', 'supabase/migracion-54-rangos-nuevos.sql').trim().split('\n').pop();
  const sinStorage = (texto) => {
    const t = texto.replace(/\r\n/g, '\n');
    const ini = t.indexOf('-- STORAGE: bucket privado de fotos');
    const fin = t.indexOf('-- PERMISOS (capa extra debajo de la RLS)');
    return ini === -1 || fin === -1 ? t : t.slice(0, t.lastIndexOf('-- ----', ini)) + t.slice(t.lastIndexOf('-- ----', fin));
  };
  const migracion = (n) => {
    const archivo = readdirSync(aqui).find((f) => f.startsWith(`migracion-${n}-`));
    return leer173(join(aqui, archivo), 'utf8').replace(/\r\n/g, '\n');
  };

  const prod = new PGlite();
  await prod.exec(`set timezone = 'UTC'`);
  await prod.exec(`
    create schema if not exists auth;
    create table auth.users (id uuid primary key default gen_random_uuid(), raw_user_meta_data jsonb default '{}'::jsonb);
    create function auth.uid() returns uuid language sql stable as $fn$
      select nullif(current_setting('test.uid', true), '')::uuid;
    $fn$;
    create role authenticated;
    create role anon;
    create role service_role;
  `);
  await prod.exec(sinStorage(git('show', `${la54}^:supabase/schema.sql`)));

  const version = async () => (await prod.query(`select version_del_esquema() as v`)).rows[0].v;
  const vidas = (n) =>
    prod.query(
      `create or replace function public.impulsos_ganados(p_user uuid)
       returns int language sql stable security definer set search_path = public
       as $fn$ select case when p_user is null then 0 else ${n} end $fn$`
    );
  const cuenta = async () => {
    const id = (await prod.query('insert into auth.users default values returning id')).rows[0].id;
    await prod.query('update profiles set username = $1 where id = $2', ['p' + id.slice(0, 8), id]);
    return id;
  };
  // Cuarenta días, ayer faltado, y hoy el día entra sin que nadie haya revisado.
  const llegarAlGimnasio = async (como) => {
    const u = await cuenta();
    for (let i = 41; i >= 2; i--) await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - $2::int)`, [u, i]);
    await prod.query(`select set_config('test.uid', $1, false)`, [u]);
    if (como === 'ubicacion') await prod.query(`select registrar_dia('ubicacion')`);
    else if (como === 'cliente') await anotarElDia(clienteDePrueba, 'ubicacion');
    else await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy())`, [u]);
    return (await prod.query(`select racha_actual from profiles where id = $1`, [u])).rows[0].racha_actual;
  };
  const puedeAnotarRutaAjena = async () => {
    const victima = await cuenta();
    const atacante = await cuenta();
    await prod.query(`select set_config('test.uid', $1, false)`, [atacante]);
    await prod.exec('set role authenticated');
    try {
      return await prod
        .query(`insert into photos (user_id, storage_path, visibilidad) values ($1, $2, 'amigos')`, [atacante, `${victima}/2026-10-04-1.jpg`])
        .then(() => true, () => false);
    } finally {
      await prod.exec('reset role');
    }
  };

  // EL PARCHE DEL CLIENTE, que es lo único que cuida al teléfono y a la web
  // MIENTRAS NO SE MIGRE. Se corre el código de verdad (`compartido/anotarDia`)
  // contra las funciones de verdad del esquema 53: el "cliente" de acá solo
  // traduce `rpc(nombre, args)` a una consulta.
  const { anotarElDia } = await import('../compartido/anotarDia.ts');
  const clienteDePrueba = {
    rpc: async (nombre, args = {}) => {
      const claves = Object.keys(args);
      try {
        const r = await prod.query(
          `select ${nombre}(${claves.map((k, i) => `${k} => $${i + 1}`).join(', ')}) as v`,
          claves.map((k) => args[k])
        );
        return { data: r.rows[0].v, error: null };
      } catch (e) {
        return { data: null, error: { code: e.code, message: e.message } };
      }
    },
  };

  await vidas(0);
  chequear('la base de la prueba es la de producción: esquema 53', await version(), 53);
  chequear('y ahí el bug está: llegar al gimnasio con ayer faltado deja la racha en 1', await llegarAlGimnasio('ubicacion'), 1);
  chequear('y la ruta ajena entra', await puedeAnotarRutaAjena(), true);
  chequear('con el parche del cliente, sobre el 53 SIN migrar: 40 - 10 + el día', await llegarAlGimnasio('cliente'), 31);
  await vidas(2);
  chequear('y con vidas, el parche del cliente gasta una y sigue', await llegarAlGimnasio('cliente'), 41);
  await vidas(0);

  // ---- HOY: la 59 y la 60 sueltas, sobre el 53 ----
  await prod.exec(migracion(59));
  await prod.exec(migracion(60));
  chequear('la 59 y la 60 corren sobre el 53 y NO suben la versión', await version(), 53);
  chequear('con la 59, por ubicación: 40 - 10 + el día', await llegarAlGimnasio('ubicacion'), 31);
  chequear('y desde el calendario igual', await llegarAlGimnasio('calendario'), 31);
  await vidas(2);
  chequear('y con vidas se gasta una y sigue', await llegarAlGimnasio('ubicacion'), 41);
  await vidas(0);
  chequear('con la 60, la ruta ajena no entra', await puedeAnotarRutaAjena(), false);
  chequear('abrir Inicio sigue contestando lo de siempre',
    Object.keys((await prod.query(`select verificar_perdida() as v`)).rows[0].v).sort(), ['pendiente_resuelto', 'perdida']);

  await prod.exec(migracion(59));
  await prod.exec(migracion(60));
  chequear('correrlas dos veces no rompe ni sube nada', [await version(), await llegarAlGimnasio('ubicacion')], [53, 31]);

  // ---- LA 61 NO ES DE HOY: va en su lugar, después de la 60 ----
  // Vuelve a definir `logs_after_change`, que desde la 57 escribe una columna
  // que el 53 no tiene. Corrida antes rompería el registro de días, así que se
  // niega sola.
  const negada = await prod.exec(migracion(61)).then(() => 'corrió', (e) => e.message);
  chequear('la 61 se niega a correr sobre el 53', /va después de la 60/.test(negada), true);
  chequear('y no dejó nada tocado: la versión, y el día sigue entrando', [await version(), await llegarAlGimnasio('ubicacion')], [53, 31]);

  // ---- EL DÍA DE LA APROBACIÓN: 54 a 58 encima, y después la 59 y la 60 de nuevo ----
  for (const n of [54, 55, 56, 57, 58]) await prod.exec(migracion(n));
  chequear('con la 54 a la 58 encima la versión es 58', await version(), 58);
  // La 55 vuelve a definir `verificar_perdida_de` con su cuerpo de antes. El
  // disparador de la 59 sigue puesto: la racha sigue cuidada en el medio.
  chequear('y la racha sigue cuidada antes de volver a correr la 59', await llegarAlGimnasio('ubicacion'), 31);
  await prod.exec(migracion(59));
  chequear('la 59 en su lugar sube a 59', await version(), 59);
  await prod.exec(migracion(60));
  chequear('y la 60 a 60', await version(), 60);
  // LA 61, EN SU LUGAR (sección 186). 40 días, uno faltado, 25 días, otro
  // faltado y un día más: la racha fue 40, 30, 55, 45 y 46. El récord es 55.
  const recordArrastrado = async () => {
    const u = await cuenta();
    for (const [desde, hasta] of [[69, 30], [28, 4], [2, 2]]) {
      for (let i = desde; i >= hasta; i--) await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - $2::int)`, [u, i]);
    }
    return u;
  };
  const rachaYRecord = async (u) => {
    const p = (await prod.query(`select racha_actual, mejor_racha from profiles where id = $1`, [u])).rows[0];
    return [p.racha_actual, p.mejor_racha];
  };
  // La consulta de comprobación del runbook (spec/dia-de-aprobacion.md §2.9).
  const comprobar61 = async () => {
    const f = (
      await prod.query(
        `select public.version_del_esquema() as version,
                to_regprocedure('public.techo_de_mejor_racha(uuid)') is not null as hay_techo,
                (select prosrc like '%techo_de_mejor_racha%' from pg_proc
                  where oid = 'public.logs_after_change()'::regprocedure) as el_record_no_baja_solo`
      )
    ).rows[0];
    return [f.version, f.hay_techo, f.el_record_no_baja_solo];
  };
  const deAntes = await recordArrastrado();
  chequear('con la 60 puesta el bug sigue: el récord de 55 baja a 46 sin que se borre nada', await rachaYRecord(deAntes), [46, 46]);
  chequear('la consulta del runbook, antes de la 61', await comprobar61(), [60, false, false]);
  await prod.exec(migracion(61));
  chequear('y la 61 a 61', await version(), 61);
  chequear('la consulta del runbook, después', await comprobar61(), [61, true, true]);
  chequear('con la 61, el récord de 55 se queda en 55', await rachaYRecord(await recordArrastrado()), [46, 55]);
  // No hay cómo saber qué número llegó a ver cada persona: no se inventa.
  chequear('y a quien el bug ya se lo había bajado NO se le sube solo', await rachaYRecord(deAntes), [46, 46]);
  // La consulta del runbook que lista a quién mirar a mano, y la corrección.
  const porMirar = (
    await prod.query(
      `select id, mejor_racha, public.techo_de_mejor_racha(id) as techo
         from public.profiles where public.techo_de_mejor_racha(id) > mejor_racha order by 3 desc`
    )
  ).rows;
  chequear('esa cuenta sale en la lista de las que hay que mirar a mano, con su techo', porMirar.filter((f) => f.id === deAntes).map((f) => [f.mejor_racha, f.techo]), [[46, 55]]);
  await prod.query(`update public.profiles set mejor_racha = 55 where id = $1`, [deAntes]);
  await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - 1)`, [deAntes]);
  chequear('corregida a mano, el día siguiente no se la vuelve a bajar', await rachaYRecord(deAntes), [47, 55]);
  await prod.exec(migracion(61));
  chequear('correrla dos veces no cambia nada', [await version(), await rachaYRecord(deAntes)], [61, [47, 55]]);
  chequear('al final: la racha', await llegarAlGimnasio('ubicacion'), 31);
  chequear('y la foto', await puedeAnotarRutaAjena(), false);

  // ================= LA 62: el día en todos los caminos, y una sola escalera =================
  //
  // Se arma lo que producción tenía el 6/10, con la 61 puesta: días con su
  // número (el relleno de la 57), planetas de la escalera VIEJA del 30 al 39 y
  // nada del 40 en adelante, y dos días nacidos sin número (el calendario).
  const VIEJA = ['Ceres', 'Plutón', 'Mercurio', 'Marte', 'Venus', 'Tierra', 'Neptuno', 'Urano', 'Saturno', 'Júpiter'];
  const dias62 = async (u) =>
    (await prod.query(`select (mi_hoy() - fecha)::int as hace, racha_del_dia as dia, planeta_del_dia as planeta from logs where user_id = $1 order by fecha`, [u])).rows;
  const comoEnProduccion = async (u, conNumeroHasta) => {
    const filas = (await prod.query(`select id from logs where user_id = $1 order by fecha`, [u])).rows;
    for (let i = 0; i < filas.length; i++) {
      const dia = i + 1;
      await prod.query(`update logs set racha_del_dia = $2, planeta_del_dia = $3 where id = $1`, [filas[i].id, dia <= conNumeroHasta ? dia : null, dia >= 30 && dia <= 39 ? VIEJA[dia - 30] : null]);
    }
  };
  // Nunca perdió: 45 días seguidos, los dos últimos sin número.
  const sinPerder = await cuenta();
  for (let i = 45; i >= 1; i--) await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - $2::int)`, [sinPerder, i]);
  await comoEnProduccion(sinPerder, 43);
  // Perdió después: 40 días, y la pérdida más acá. Sus días no tienen número.
  const conPerdida = await cuenta();
  for (let i = 50; i >= 11; i--) await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - $2::int)`, [conPerdida, i]);
  await comoEnProduccion(conPerdida, 0);
  await prod.query(`update profiles set perdida_fecha = mi_hoy() - 5, racha_base = 30, racha_actual = 30 where id = $1`, [conPerdida]);
  const elDia = (filas, n) => filas[n - 1];
  const antes62 = await dias62(sinPerder);
  chequear('antes de la 62: nombres de la escalera vieja, nada del 40 en adelante, y días sin número', [elDia(antes62, 31).planeta, elDia(antes62, 39).planeta, elDia(antes62, 40).planeta, elDia(antes62, 45).dia], ['Plutón', 'Júpiter', null, null]);

  // La consulta de comprobación del runbook (spec/dia-de-aprobacion.md §2.10).
  const comprobar62 = async () => {
    const f = (
      await prod.query(
        `select public.version_del_esquema() as version,
                (select count(*) from public.logs l join public.profiles p on p.id = l.user_id
                  where not l.es_descanso and l.racha_del_dia is null
                    and (p.perdida_fecha is null or l.fecha > p.perdida_fecha))::int as sin_numero,
                (select count(*) from public.logs
                  where racha_del_dia is not null
                    and planeta_del_dia is distinct from public.planeta_de_dia(racha_del_dia))::int as planeta_desfasado,
                (select count(*) from public.logs
                  where planeta_del_dia in ('Plutón','Tierra','Neptuno','Urano','Júpiter'))::int as nombres_viejos`
      )
    ).rows[0];
    return [f.version, f.sin_numero > 0, f.planeta_desfasado > 0, f.nombres_viejos > 0];
  };
  chequear('la consulta del runbook, antes de la 62', await comprobar62(), [61, true, true, true]);
  await prod.exec(migracion(62));
  chequear('y la 62 a 62', await version(), 62);
  chequear('la consulta del runbook, después', await comprobar62(), [62, false, false, false]);
  const despues62 = await dias62(sinPerder);
  chequear('todos los días tienen su número, del 1 al 45', despues62.map((f) => f.dia), Array.from({ length: 45 }, (_, i) => i + 1));
  chequear('y el planeta es el de la escalera de hoy: del 31 al 50, de Ceres a Saturno', [30, 31, 34, 35, 39, 40, 43, 45].map((n) => elDia(despues62, n).planeta), [null, 'Ceres', 'Ceres', 'Mercurio', 'Marte', 'Marte', 'Venus', 'Venus']);
  const perdio62 = await dias62(conPerdida);
  chequear('los de antes de la pérdida siguen SIN número: no se inventa', perdio62.every((f) => f.dia === null), true);
  // Día 30 era Ceres (afuera de la escalera nueva), 31 Plutón, 35 Tierra, 39 Júpiter.
  chequear('y su planeta se tradujo por nombre', [29, 30, 31, 35, 39, 40].map((n) => elDia(perdio62, n).planeta), [null, null, 'Ceres', 'Mercurio', 'Marte', null]);
  await prod.exec(migracion(62));
  chequear('correrla dos veces no vuelve a traducir lo traducido', [await version(), (await dias62(conPerdida)).map((f) => f.planeta), (await dias62(sinPerder)).map((f) => f.dia)], [62, perdio62.map((f) => f.planeta), despues62.map((f) => f.dia)]);

  // ---- Y DE ACÁ EN ADELANTE, CUALQUIER CAMINO ESCRIBE EL NÚMERO ----
  const numeros = async (u) => (await dias62(u)).map((f) => [f.hace, f.dia]);
  const nuevo62 = await cuenta();
  // A mano desde el calendario: el cliente inserta la fila, sin `registrar_dia`.
  for (const hace of [6, 5, 4, 3, 2]) await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - $2::int)`, [nuevo62, hace]);
  chequear('un día marcado a mano desde el calendario nace con su número', await numeros(nuevo62), [[6, 1], [5, 2], [4, 3], [3, 4], [2, 5]]);
  // Corregir un día viejo corre el número de todos los de después.
  await prod.query(`delete from logs where user_id = $1 and fecha = mi_hoy() - 4`, [nuevo62]);
  chequear('sacar un día viejo corre el número de los de después', await numeros(nuevo62), [[6, 1], [5, 2], [3, 1], [2, 2]]);
  await prod.query(`insert into logs (user_id, fecha, es_descanso) values ($1, mi_hoy() - 4, true)`, [nuevo62]);
  chequear('y un descanso en el hueco los vuelve a unir, sin llevar número él', await numeros(nuevo62), [[6, 1], [5, 2], [4, null], [3, 3], [2, 4]]);
  // El pendiente de cambio de zona: el día lo pone la base, sin `registrar_dia`.
  const conPendiente = await cuenta();
  for (const hace of [2, 1]) await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - $2::int)`, [conPendiente, hace]);
  await prod.query(`update profiles set dia_pendiente = mi_hoy(), pendiente_desde = now() - interval '2 days' where id = $1`, [conPendiente]);
  await prod.query(`select resolver_pendiente($1)`, [conPendiente]);
  chequear('el día que entra por el pendiente de cambio de zona, también', await numeros(conPendiente), [[2, 1], [1, 2], [0, 3]]);
  // Antes de la última pérdida no hay cuenta posible: ni número ni planeta inventados.
  await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - 8)`, [conPerdida]);
  const metido = (await dias62(conPerdida)).find((f) => f.hace === 8);
  chequear('un día agregado antes de la última pérdida queda sin número y sin planeta', [metido.dia, metido.planeta], [null, null]);
  chequear('y no les cambia nada a los demás de esa cuenta', (await dias62(conPerdida)).filter((f) => f.hace !== 8).map((f) => f.planeta), perdio62.map((f) => f.planeta));

  // ---- UNA ETIQUETA QUE FALLA NO FRENA EL DÍA ----
  // Un error en un disparador aborta la inserción entera. Se rompe a propósito
  // la cuenta del planeta —de la que cuelgan las dos etiquetas— y se registra
  // un día por los tres caminos: tiene que entrar igual, con su racha.
  const escalera = (await prod.query(`select pg_get_functiondef('public.planeta_de_dia(int)'::regprocedure) as def`)).rows[0].def;
  await prod.exec(`create or replace function public.planeta_de_dia(r int) returns text language plpgsql immutable as $f$ begin raise exception 'escalera rota a propósito'; end $f$`);
  const conFalla = await cuenta();
  await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - 2)`, [conFalla]);
  await prod.query(`select set_config('test.uid', $1, false)`, [conFalla]);
  await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - 1)`, [conFalla]);
  const porRegistrar = (await prod.query(`select registrar_dia('manual') as r`)).rows[0].r;
  chequear('con la cuenta de las etiquetas rota, el día entra igual por los tres caminos', [
    (await numeros(conFalla)).map((f) => f[0]),
    (await prod.query(`select racha_actual from profiles where id = $1`, [conFalla])).rows[0].racha_actual,
    porRegistrar.racha,
  ], [[2, 1, 0], 3, 3]);
  await prod.query(`delete from logs where user_id = $1 and fecha = mi_hoy() - 1`, [conFalla]);
  chequear('y borrar un día tampoco se frena', (await numeros(conFalla)).map((f) => f[0]), [2, 0]);
  await prod.exec(escalera);
  // Arreglada la cuenta, el cambio siguiente numera desde el día que cambió en
  // adelante. El de más atrás, que entró durante la falla, queda sin número
  // hasta que se corra un relleno: se pierde una etiqueta, no un día.
  await prod.query(`insert into logs (user_id, fecha) values ($1, mi_hoy() - 1)`, [conFalla]);
  chequear('con la cuenta arreglada, el cambio siguiente numera de ahí en adelante', (await numeros(conFalla)).map((f) => f[1]), [null, 2, 3]);
  await prod.close();
}

console.log('\n174. Anotar el día: la revisión de la pérdida va adelante también en el cliente');
{
  const { anotarElDia, revisarPerdidaAntes, SIN_REVISAR } = await import('../compartido/anotarDia.ts');
  const llamadas = [];
  const cliente = (respuestas = {}) => ({
    rpc: async (nombre, args) => {
      llamadas.push([nombre, args ?? null]);
      return respuestas[nombre] ?? { data: null, error: null };
    },
  });

  const bien = await anotarElDia(cliente({ registrar_dia: { data: { racha: 5 }, error: null } }), 'ubicacion');
  chequear('primero revisa y después registra, con el origen que le dieron', llamadas, [
    ['verificar_perdida', null],
    ['registrar_dia', { p_origen: 'ubicacion' }],
  ]);
  chequear('y devuelve lo que contestó la base', bien, { data: { racha: 5 }, error: null });

  // SI NO SE PUDO REVISAR, NO SE REGISTRA: registrar igual es el bug.
  llamadas.length = 0;
  const sinRed = await anotarElDia(cliente({ verificar_perdida: { data: null, error: { message: 'Network request failed' } } }), 'manual');
  chequear('si la revisión falla, no llega a registrar', llamadas.map(([nombre]) => nombre), ['verificar_perdida']);
  chequear('y lo devuelve como un error', sinRed, { data: null, error: SIN_REVISAR });
  chequear('revisar dice si se pudo', [
    await revisarPerdidaAntes(cliente()),
    await revisarPerdidaAntes(cliente({ verificar_perdida: { data: null, error: { message: 'x' } } })),
  ], [true, false]);

  // ---- EL CABLEADO: que nadie anote el día por un costado ----
  const { readFileSync: leer174, readdirSync: listar174 } = await import('node:fs');
  const raiz174 = join(dirname(fileURLToPath(import.meta.url)), '..');
  const fuentes = [];
  const recorrer174 = (carpeta) => {
    for (const e of listar174(join(raiz174, carpeta), { withFileTypes: true })) {
      const ruta = `${carpeta}/${e.name}`;
      if (e.isDirectory()) {
        if (e.name !== 'node_modules') recorrer174(ruta);
      } else if (/\.tsx?$/.test(e.name)) fuentes.push(ruta);
    }
  };
  for (const c of ['compartido', 'nucleo', 'src', 'movil/src', 'movil/app']) recorrer174(c);
  const codigo = (ruta) => sinComentarios(leer174(join(raiz174, ruta), 'utf8'));

  chequear('`registrar_dia` se llama desde un solo archivo',
    fuentes.filter((f) => /rpc\(\s*'registrar_dia'/.test(codigo(f))), ['compartido/anotarDia.ts']);

  // Empezar la sesión también anota el día: la revisión va antes del pedido.
  const sesion174 = codigo('compartido/useSesion.ts');
  const iniciar174 = sesion174.slice(sesion174.indexOf('async function iniciar('), sesion174.indexOf('async function cerrar('));
  chequear('empezar la sesión revisa antes de pedirla',
    iniciar174.includes('revisarPerdidaAntes(supabase)') &&
      iniciar174.indexOf('revisarPerdidaAntes(supabase)') < iniciar174.indexOf("rpc('iniciar_sesion'"), true);
  chequear('y `iniciar_sesion` tampoco se llama por otro lado',
    fuentes.filter((f) => /rpc\(\s*'iniciar_sesion'/.test(codigo(f))), ['compartido/useSesion.ts']);

  // Y el calendario, que inserta directo: marcar HOY revisa antes de tocar nada.
  const dia174 = codigo('compartido/dia.ts');
  const corregir174 = dia174.slice(dia174.indexOf('export async function corregirDia('), dia174.indexOf('export function queHacer('));
  chequear('marcar hoy desde el calendario revisa antes de borrar o insertar',
    /fecha === hoyISO\(\) && !\(await revisarPerdidaAntes\(supabase\)\)/.test(corregir174) &&
      corregir174.indexOf('revisarPerdidaAntes(supabase)') < corregir174.indexOf(".from('logs')"), true);
  chequear('y es el único lugar del cliente que inserta un log a mano',
    fuentes.filter((f) => /from\('logs'\)\s*\.insert\(/.test(codigo(f))), ['compartido/dia.ts']);
}

console.log('\n175. El peso por modo en el teléfono: la copia del perfil tiene quien la escriba');
{
  // POR QUÉ LA SECCIÓN 166 DABA VERDE Y EN EL TELÉFONO NO ANDABA (4/10). La 166
  // prueba la CUENTA (`nucleo/pesoRecordado`). Lo que la usa es
  // `compartido/pesosRecordados`, que para saber de quién es el historial lee la
  // copia del perfil guardada en el aparato. Esa copia la escribía solo la web:
  // la app nativa no la guardó nunca, así que ahí "¿quién soy?" contestaba
  // nadie y no se proponía ningún peso. Nada corría ese archivo.
  //
  // Acá se corre el archivo DE VERDAD, con el almacenamiento como lo deja cada
  // app. Los alias los resuelve `dobles/alias.mjs`.
  const { register } = await import('node:module');
  register('./dobles/alias.mjs', import.meta.url);
  const { memoria } = await import('./dobles/plataforma.mjs');
  const R = await import('../compartido/pesosRecordados.ts');
  const { guardarPerfilCache } = await import('../compartido/cache.ts');

  const REMO = 'remo_mancuerna';
  const historial = [
    { bloques: [{ ejercicio: REMO, series: 3, pesos: [50, 50, 50], carga: 'total' }] },
    { bloques: [{ ejercicio: REMO, series: 3, pesos: [20, 20, 22], carga: 'par' }] },
  ];
  const consulta = (resultado) => {
    const c = { select: () => c, neq: () => c, gte: () => c, order: () => c, then: (bien, mal) => Promise.resolve(resultado).then(bien, mal) };
    return c;
  };
  let pedidos = 0;
  const base = {
    from: (tabla) => {
      pedidos++;
      return consulta(tabla === 'sesiones' ? { data: historial, error: null } : { data: [{ id: REMO, carga: 'total' }], error: null });
    },
  };
  const perfilDe = (id) => ({
    id, username: id, avatar_url: null, racha_actual: 3, mejor_racha: 3, rango_actual: 1, racha_base: 0,
    perdida_fecha: null, dias_descanso: [], duracion_descanso: 90, dia_pendiente: null,
  });

  // ---- COMO ESTABA EL TELÉFONO: nadie guardó la copia ----
  memoria.clear();
  chequear('sin la copia del perfil no hay de quién sea el historial: no propone nada',
    [await R.traerRecordados(base), pedidos], [{ pesos: {}, catalogo: {}, maximos: {}, subidas: {}, paraSubir: {} }, 0]);

  // ---- COMO QUEDA DESPUÉS DE CARGAR INICIO, que ahora la guarda ----
  await guardarPerfilCache(perfilDe('cuenta-a'));
  const traidos = await R.traerRecordados(base);
  chequear('con la copia, trae el historial y guarda un peso por modo', traidos.pesos[REMO], { total: 50, par: 22 });
  chequear('y queda en el aparato, para el subsuelo sin señal', (await R.leerRecordados()).pesos[REMO], { total: 50, par: 22 });
  chequear('guardado con su dueño', JSON.parse(memoria.get('ascent:pesos-por-modo')).de, 'cuenta-a');

  // ---- Y NO SE CRUZA DE CUENTA ----
  await guardarPerfilCache(perfilDe('cuenta-b'));
  chequear('otra cuenta en el mismo teléfono no ve los pesos de la anterior', await R.leerRecordados(), { pesos: {}, catalogo: {}, maximos: {}, subidas: {}, paraSubir: {} });

  // ---- LO MÁS PESADO DE LA ÚLTIMA VEZ, para la lista de ejercicios (10/10) ----
  // Por el mismo camino: lo que trae la base, lo que queda en el aparato, y lo
  // que suma una sesión recién terminada.
  await guardarPerfilCache(perfilDe('cuenta-a'));
  chequear('la copia trae además lo más pesado de la última vez, con su modo', (await R.traerRecordados(base)).maximos[REMO], { peso: 22, carga: 'par' });
  chequear('y eso también queda en el aparato', (await R.leerRecordados()).maximos[REMO], { peso: 22, carga: 'par' });
  await R.sumarSesionARecordados([
    { ejercicio: REMO, series: 2, pesos: [24, 26], carga: 'par' },
    { ejercicio: 'sentadilla', series: 1, pesos: [100], carga: 'total' },
    { ejercicio: REMO, series: 1, pesos: [25], carga: 'par' },
  ]);
  chequear('terminar una sesión lo actualiza sin esperar a la base', (await R.leerRecordados()).maximos, {
    [REMO]: { peso: 26, carga: 'par' }, sentadilla: { peso: 100, carga: 'total' },
  });
  // AL REABRIR LA APP se lee del aparato, no de la memoria. Pasar por otra
  // cuenta y volver es lo que tira la copia en memoria: lo que vuelve salió
  // del almacenamiento. (Sin esto, perder los máximos al leer pasaba en verde.)
  await guardarPerfilCache(perfilDe('cuenta-b'));
  await R.leerRecordados();
  await guardarPerfilCache(perfilDe('cuenta-a'));
  chequear('y al reabrir la app sigue ahí: se lee del aparato', (await R.leerRecordados()).maximos, {
    [REMO]: { peso: 26, carga: 'par' }, sentadilla: { peso: 100, carga: 'total' },
  });
  const PR197 = await import('../nucleo/pesoRecordado.ts');
  const cat197 = { press_banca: 'total', dominadas: 'corporal', remo: 'total' };
  chequear('es lo más pesado de la ÚLTIMA sesión, no de la historia; lo que no se repitió queda; sin número no hay nada', PR197.maximosDelHistorial([
    { bloques: [{ ejercicio: 'press_banca', pesos: [80, 90, 85] }, { ejercicio: 'remo', pesos: [70] }] },
    { bloques: [{ ejercicio: 'press_banca', pesos: [60, 62.5] }, { ejercicio: 'press_banca', pesos: [55] }, { ejercicio: 'dominadas', pesos: [10] }, { ejercicio: 'remo', pesos: [] }] },
  ], cat197), { press_banca: { peso: 62.5, carga: 'total' }, remo: { peso: 70, carga: 'total' } });
  chequear('lo guardado con otra forma se descarta', PR197.leerMaximos({ a: { peso: 60, carga: 'total' }, b: { peso: 'x', carga: 'total' }, c: { peso: 5, carga: 'corporal' }, d: null }), { a: { peso: 60, carga: 'total' } });
  const { T: T166 } = await import('../nucleo/textos.ts');
  chequear('en la lista se lee corto, y por mancuerna lo dice', [T166.resumen.pesoEnLista('60 kg', 'total'), T166.resumen.pesoEnLista('30 kg', 'par'), T166.resumen.pesoEnLista('20 kg', 'parPolea')], ['60 kg', '30 kg c/u', '20 kg c/lado']);
  const { readFileSync: leerSel } = await import('node:fs');
  const sel197 = sinComentarios(leerSel(new URL('../movil/src/SelectorEjercicio.tsx', import.meta.url), 'utf8'));
  chequear('la lista de ejercicios lo muestra al lado de cada nombre, en la unidad de la persona', [
    (sel197.match(/extra=\{ultimos\[e\.id\]\}/g) ?? []).length,
    /pesoEnLaLista\(m\.peso, unidad\), claveDeEtiqueta\(m\.carga, id\)/.test(sel197),
    /leerRecordados\(\)\.then\(poner\)\.then\(\(\) => recordadosAlDia\(supabase\)\)\.then\(poner\)/.test(sel197),
  ], [4, true, true]);

  // ---- EL CABLEADO: las DOS apps guardan la copia donde cargan el perfil ----
  // `compartido/` la lee desde las dos; si una sola la escribe, en la otra todo
  // lo que la lee queda muerto sin dar ningún error.
  const { readFileSync: leer175 } = await import('node:fs');
  const raiz175 = join(dirname(fileURLToPath(import.meta.url)), '..');
  const inicioDe = { nativa: 'movil/src/Inicio.tsx', web: 'src/app/page.tsx' };
  chequear('la web y la nativa guardan la copia del perfil al cargar Inicio',
    Object.fromEntries(
      Object.entries(inicioDe).map(([app, ruta]) => [app, /guardarPerfilCache\(/.test(sinComentarios(leer175(join(raiz175, ruta), 'utf8')))])
    ),
    { nativa: true, web: true });
}

console.log('\n176. El rango que se ve sale de la racha, y de ningún otro lado');
{
  // EL BUG (4/10): con racha 43, Stats decía "Planeta" y el fondo dibujaba el
  // Sol. El nombre salía de la racha con la tabla del cliente; el fondo, la
  // insignia, los colores y la subida, del número que guarda la base con la
  // suya. Con la migración 54 sin aplicar, las dos tablas no eran la misma.
  const RG = await import('../nucleo/rangos.ts');

  chequear('racha 43: Planeta y Venus, los dos de la misma racha', RG.cuerpoDe(43), { rango: 4, planeta: 'Venus' });
  chequear('sin racha todavía: Polvo, sin planeta', [RG.cuerpoDe(null), RG.cuerpoDe(undefined), RG.cuerpoDe(NaN)], [
    { rango: 1, planeta: null },
    { rango: 1, planeta: null },
    { rango: 1, planeta: null },
  ]);

  // DÍA POR DÍA: lo que se dibuja y lo que se nombra son el mismo rango, hay
  // planeta solo en Planeta, y nunca sale un número que el cliente no sepa
  // dibujar (el "rango 8" que mandaba la base vieja dejaba el cielo vacío).
  const malos = [];
  for (let r = 0; r <= 200; r++) {
    const c = RG.cuerpoDe(r);
    if (c.rango !== RG.rangoDeRacha(r).n || (c.planeta !== null) !== (c.rango === 4) || !RG.RANGOS.some((x) => x.n === c.rango)) malos.push(r);
  }
  chequear('del 0 al 200, el fondo y el nombre son el mismo rango', malos, []);

  // ---- LA SUBIDA, con la regla del cliente ----
  chequear('del 30 al 31 se sube a Planeta', RG.subidaDeRango(30, 31), { antes: 3, despues: 4 });
  chequear('del 39 al 40 no se sube a nada (lo celebraba la base vieja)', RG.subidaDeRango(39, 40), null);
  chequear('se celebra exactamente en los umbrales, ni un día antes ni uno después',
    Array.from({ length: 131 }, (_, r) => r).filter((r) => RG.subidaDeRango(r - 1, r) !== null), [...DESDE_RANGO.slice(1)]);
  // Quien tenía Luna (25), pierde 10 y al registrar queda en 16 —el primer día
  // de Luna— no subió: se compara con lo que se VEÍA, no con el día anterior.
  chequear('perder 10 y volver a cruzar el umbral del rango que ya se veía no es subir', RG.subidaDeRango(25, 16), null);
  chequear('sin racha vista se compara con el día anterior', [RG.subidaDeRango(null, 6), RG.subidaDeRango(null, 7)], [{ antes: 1, despues: 2 }, null]);
  chequear('y sin número no inventa una subida', RG.subidaDeRango(5, NaN), null);

  // ---- EL CABLEADO: que ninguna pantalla vuelva a la otra fuente ----
  const { readFileSync: leer176, readdirSync: listar176 } = await import('node:fs');
  const raiz176 = join(dirname(fileURLToPath(import.meta.url)), '..');
  const fuentes176 = [];
  const recorrer176 = (carpeta) => {
    for (const e of listar176(join(raiz176, carpeta), { withFileTypes: true })) {
      const ruta = `${carpeta}/${e.name}`;
      if (e.isDirectory()) {
        if (e.name !== 'node_modules') recorrer176(ruta);
      } else if (/\.tsx?$/.test(e.name)) fuentes176.push(ruta);
    }
  };
  for (const c of ['compartido', 'src', 'movil/src', 'movil/app']) recorrer176(c);
  const codigo176 = (ruta) => sinComentarios(leer176(join(raiz176, ruta), 'utf8'));

  chequear('ninguna pantalla lee el rango que guarda la base',
    fuentes176.filter((f) => /\.rango_actual\b/.test(codigo176(f))), []);
  chequear('ni lo pide en una consulta',
    fuentes176.filter((f) => /select\([^)]*rango_actual/.test(codigo176(f))), []);
  chequear('ni le pregunta a la base si hubo subida',
    fuentes176.filter((f) => /\.(subio_rango|rango_antes|rango_despues)\b/.test(codigo176(f))), []);
  // LOS TRES CAMINOS QUE REGISTRAN EL DÍA —el toque, empezar la sesión y el
  // gimnasio— celebran con la regla del cliente, en las dos apps. Y el
  // vigilante avisa siempre que el día entró: quién subió lo decide Inicio.
  for (const [app, ruta] of [['nativa', 'movil/src/Inicio.tsx'], ['web', 'src/app/page.tsx']]) {
    chequear(`${app}: los tres caminos celebran comparando con la racha que se veía`,
      (codigo176(ruta).match(/setSubida\(subidaDeRango\(rachaVista\.current, r\.racha\)\)/g) ?? []).length, 3);
  }
  chequear('los dos vigilantes avisan que el día entró, sin preguntarle a la base si subió',
    ['movil/src/VigilanteDeGimnasio.tsx', 'src/components/VigilanteDeGimnasio.tsx'].map((f) =>
      /if \(reg\) eventos\.emitir\(SUBIO_RANGO, reg\)/.test(codigo176(f))
    ), [true, true]);

  // QUE EL DETECTOR SIRVA: las tres formas en que se leía antes.
  chequear('el detector caza las lecturas de antes', [
    /\.rango_actual\b/.test(sinComentarios('<FondoEspacial rango={perfil.rango_actual} />')),
    /select\([^)]*rango_actual/.test(sinComentarios(".select('rango_actual, racha_actual')")),
    /\.(subio_rango|rango_antes|rango_despues)\b/.test(sinComentarios('if (r?.subio_rango) setSubida({ antes: r.rango_antes })')),
  ], [true, true, true]);
}

console.log('\n177. La app nativa no manda al login por no tener señal');
{
  // EL BUG (4/10). Sin señal y con más de una hora desde el último uso —el
  // subsuelo del gimnasio—, `getSession()` no puede renovar el token y devuelve
  // "sin sesión" CON un error. El layout miraba solo la sesión, y aparecía el
  // login en pleno entrenamiento. Es el bug del middleware de la web
  // (trampas.md, "La app te desloguea sola") por otro camino.
  const V = await import('../nucleo/veredicto.ts');
  const DE_RED = { name: 'AuthRetryableFetchError', status: 0 };

  chequear('con sesión: adentro', V.sesionSegun(true, null), 'con');
  chequear('sin sesión y sin error: nunca entró, o salió', V.sesionSegun(false, null), 'sin');
  chequear('sin sesión porque no se pudo renovar sin red: NO se sabe', V.sesionSegun(false, DE_RED), 'no-se');
  chequear('un 500 o un límite de pedidos tampoco dicen que no haya sesión',
    [V.sesionSegun(false, { status: 500 }), V.sesionSegun(false, { status: 429 }), V.sesionSegun(false, {})], ['no-se', 'no-se', 'no-se']);
  chequear('el servidor diciendo que no, sí', [V.sesionSegun(false, { status: 401 }), V.sesionSegun(false, { status: 403 })], ['sin', 'sin']);

  // ---- qué hace el layout con eso ----
  chequear('en pleno uso, no saber deja todo como estaba', V.trasMirar('con', 'no-se'), 'con');
  // Un error al renovar solo aparece si HABÍA una sesión guardada.
  chequear('al arrancar, no saber es entrar con la sesión guardada', V.trasMirar('mirando', 'no-se'), 'con');
  chequear('y no saber no saca del login a quien estaba en el login', V.trasMirar('sin', 'no-se'), 'sin');
  chequear('saber manda', [V.trasMirar('con', 'sin'), V.trasMirar('sin', 'con'), V.trasMirar('sin-nombre', 'con')], ['sin', 'con', 'con']);

  // ---- los avisos de Supabase ----
  chequear('un aviso con sesión: adentro', V.trasElAviso('TOKEN_REFRESHED', true), 'con');
  chequear('salir de verdad es SIGNED_OUT', V.trasElAviso('SIGNED_OUT', false), 'sin');
  // Al abrir sin señal con el token vencido, el aviso inicial llega vacío.
  chequear('el aviso inicial vacío no alcanza: hay que preguntar', V.trasElAviso('INITIAL_SESSION', false), 'preguntar');

  // ---- EL CABLEADO ----
  const { readFileSync: leer177 } = await import('node:fs');
  const raiz177 = join(dirname(fileURLToPath(import.meta.url)), '..');
  const layout = sinComentarios(leer177(join(raiz177, 'movil', 'app', '_layout.tsx'), 'utf8'));
  const cableado177 = (texto) => ({
    // Desde la tanda 2 no lo pregunta él: se lo pregunta a `quienSoy`, que es el
    // único que mira el error (sección 187).
    miraElError: /const quien = await quienSoy\(supabase\);\s*const visto = quien\.estado;/.test(texto),
    noPisaLoQueHabia: /setSesion\(\(actual\) => trasMirar\(actual, visto\)\)/.test(texto),
    elAvisoNoDecideSolo: /trasElAviso\(evento, !!viva\)/.test(texto) && !/setSesion\(viva \? 'con' : 'sin'\)/.test(texto),
    yNoConcluyeDeLaSesionSola: !/setSesion\(data\.session \? 'con' : 'sin'\)/.test(texto),
  });
  chequear('el layout decide con el error a la vista y no pisa lo que había', cableado177(layout), {
    miraElError: true,
    noPisaLoQueHabia: true,
    elAvisoNoDecideSolo: true,
    yNoConcluyeDeLaSesionSola: true,
  });
  // QUE EL DETECTOR SIRVA: el layout como estaba.
  chequear('el layout de antes no pasa', cableado177(
    "const { data } = await supabase.auth.getSession(); setSesion(data.session ? 'con' : 'sin'); supabase.auth.onAuthStateChange((_evento, viva) => { setSesion(viva ? 'con' : 'sin'); });"
  ), { miraElError: false, noPisaLoQueHabia: false, elAvisoNoDecideSolo: false, yNoConcluyeDeLaSesionSola: false });

  // Inicio, sin sesión que mostrar: no se queda con la ruedita para siempre.
  const inicio177 = sinComentarios(leer177(join(raiz177, 'movil', 'src', 'Inicio.tsx'), 'utf8'));
  // Desde la tanda 2 son dos casos: "no hay" sale, "no sé" avisa (sección 187).
  chequear('Inicio, si no se pudo preguntar quién es, avisa y deja Reintentar',
    /if \(yo\.estado === 'no-se'\) return fallo\(T\.general\.noSePudo\);/.test(inicio177), true);
}

