  chequear('una medición mala suelta no baja la calidad; dos seguidas sí', [
    correr(['mal']),
    correr(['mal', 'bien', 'mal']),
    correr(['mal', null, 'mal']),
    correr(['mal', 'mal']),
    correr(['bien', 'bien', 'bien']),
  ], [false, false, true, true, false]);
