  chequear('aceptado y sin publicar todavía: "todavía no empezó", no un renglón vacío', EV.renglonDe({ ...u201, enVivo: null }, 0), { ejercicio: null, serie: 0, meta: 0, descanso: null, pasado: null, sinSenal: false, sinDatos: true });
