  chequear('basura de la base no rompe la pantalla', [EV.leerUniones(null), EV.leerUniones([{ id: 1 }, null, { id: 'x', estado: 'otra', otro: { id: 'y' }, ahora: '2026-10-12T10:00:00Z' }])], [[], []]);
